/**
 * process-paper-generation-job — claim a leased job and run assembly.
 *
 * Auth (any one):
 *  - x-internal-secret / Bearer matching PAPER_JOB_WORKER_SECRET or INTERNAL_WORKER_SECRET
 *  - Bearer service role key
 *  - JWT admin
 *  - JWT owner (must pass jobId; owner retry / reclaim)
 */

import { handleCors, getCorsHeaders } from "../_shared/cors.ts";
import {
  authenticateRequest,
  extractBearerToken,
  isAdmin,
  unauthorizedResponse,
  forbiddenResponse,
} from "../_shared/auth.ts";
import { createServiceClient } from "../_shared/supabase.ts";
import {
  assembleClaimedPaperJob,
} from "../_shared/govPaperAssembly.ts";
import {
  claimPaperGenerationJob,
  newWorkerId,
} from "../_shared/govPaperJobLease.ts";

function json(req: Request, payload: unknown, status = 200) {
  return new Response(JSON.stringify(payload), {
    status,
    headers: { ...getCorsHeaders(req), "Content-Type": "application/json" },
  });
}

function uuidOrNull(v: unknown): string | null {
  if (typeof v !== "string") return null;
  const s = v.trim();
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(s)
    ? s
    : null;
}

function timingSafeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let out = 0;
  for (let i = 0; i < a.length; i++) out |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return out === 0;
}

function hasInternalAuth(req: Request): boolean {
  const secrets = [
    Deno.env.get("PAPER_JOB_WORKER_SECRET"),
    Deno.env.get("INTERNAL_WORKER_SECRET"),
  ].filter((s): s is string => Boolean(s && s.length > 8));

  if (secrets.length === 0) return false;

  const headerSecret = req.headers.get("x-internal-secret")?.trim() ?? "";
  const bearer = extractBearerToken(req) ?? "";

  for (const secret of secrets) {
    if (headerSecret && timingSafeEqual(headerSecret, secret)) return true;
    if (bearer && timingSafeEqual(bearer, secret)) return true;
  }
  return false;
}

Deno.serve(async (req) => {
  const cors = handleCors(req);
  if (cors) return cors;

  if (req.method !== "POST") {
    return json(req, { error: "Method not allowed", code: "METHOD_NOT_ALLOWED" }, 405);
  }

  const db = createServiceClient();

  try {
    const body = await req.json().catch(() => ({}));
    const jobId = uuidOrNull(
      body && typeof body === "object"
        ? (body as Record<string, unknown>).jobId
        : null,
    );

    const internal = hasInternalAuth(req);
    let actor: "internal" | "admin" | "owner" | null = internal ? "internal" : null;
    let userId: string | null = null;

    if (!internal) {
      const auth = await authenticateRequest(req);
      if (auth.error) return auth.error;
      userId = auth.context.user.id;
      if (await isAdmin(userId)) {
        actor = "admin";
      } else if (jobId) {
        actor = "owner";
      } else {
        return forbiddenResponse(
          "Owner calls must include jobId; omit jobId only for admin/internal workers.",
        );
      }
    }

    if (!actor) return unauthorizedResponse();

    const workerId = newWorkerId(actor === "internal" ? "svc" : actor);

    const claimed = await claimPaperGenerationJob(db, {
      jobId: jobId ?? undefined,
      workerId,
      userId: actor === "owner" && userId ? userId : undefined,
    });

    if (!claimed.ok) {
      if (claimed.reason === "max_attempts") {
        return json(req, {
          status: "failed",
          errorCode: "MAX_ATTEMPTS",
          error: "Exceeded max processing attempts",
          jobId,
        }, 422);
      }
      if (jobId) {
        const { data: existing } = await db
          .from("gov_paper_generation_jobs")
          .select("id, status, mock_test_id, generated_paper_id, error_code, user_id, request_json")
          .eq("id", jobId)
          .maybeSingle();

        if (!existing) {
          return json(req, { error: "Job not found", code: "PAPER_NOT_FOUND" }, 404);
        }
        if (actor === "owner" && userId && existing.user_id !== userId) {
          return forbiddenResponse("You do not own this job.");
        }
        if (existing.status === "completed") {
          return json(req, {
            jobId: existing.id,
            status: "completed",
            mockTestId: existing.mock_test_id,
            paperId: existing.generated_paper_id,
            idempotent: true,
          });
        }
        if (existing.status === "cancelled") {
          return json(req, {
            jobId: existing.id,
            status: "cancelled",
            errorCode: "CANCELLED",
            idempotent: true,
          });
        }
        const routedGenerator = String(
          (existing.request_json as Record<string, unknown> | null)?.generator ?? "",
        ).toLowerCase();
        if (
          routedGenerator === "python_paper_factory" ||
          routedGenerator === "python" ||
          routedGenerator === "factory"
        ) {
          return json(req, {
            jobId: existing.id,
            status: existing.status,
            code: "PYTHON_FACTORY_OWNED",
            error: "This job is owned by the Python paper-factory worker.",
            generator: routedGenerator,
          }, 202);
        }
      }
      return json(req, {
        error: claimed.message ?? "No claimable job",
        code: "NOT_CLAIMABLE",
        jobId,
      }, 409);
    }

    // Do not Edge-assemble jobs explicitly routed to the Python factory.
    const claimedGenerator = String(
      (claimed.job.request_json as Record<string, unknown> | null | undefined)?.generator ?? "",
    ).toLowerCase();
    if (
      claimedGenerator === "python_paper_factory" ||
      claimedGenerator === "python" ||
      claimedGenerator === "factory"
    ) {
      // Release the lease so the Python worker can reclaim.
      await db
        .from("gov_paper_generation_jobs")
        .update({
          status: "queued",
          worker_id: null,
          lease_expires_at: null,
          progress_stage: "queued",
        })
        .eq("id", claimed.job.id)
        .eq("worker_id", claimed.workerId);
      return json(req, {
        jobId: claimed.job.id,
        status: "queued",
        code: "PYTHON_FACTORY_OWNED",
        error: "Job released for Python paper-factory worker.",
        generator: claimedGenerator,
      }, 202);
    }

    const result = await assembleClaimedPaperJob(db, claimed.job, claimed.workerId);

    if (result.ok) {
      return json(req, {
        jobId: claimed.job.id,
        status: "completed",
        mockTestId: result.mockTestId,
        paperId: result.paperId,
        questionCount: result.questionCount,
        paperClass: result.paperClass,
        disclaimer: result.disclaimer,
        patternVersion: result.patternVersion,
        syllabusVersion: result.syllabusVersion,
        workerId: claimed.workerId,
        attemptCount: claimed.attemptCount,
      });
    }

    return json(req, {
      jobId: claimed.job.id,
      status: result.status,
      errorCode: result.errorCode,
      error: result.error,
      available: result.available,
      required: result.required,
      workerId: claimed.workerId,
      attemptCount: claimed.attemptCount,
    }, result.status === "cancelled" ? 202 : (result.httpStatus ?? 500));
  } catch (err) {
    console.error("[process-paper-generation-job]", err);
    return json(req, { error: "Internal server error", code: "INTERNAL_ERROR" }, 500);
  }
});

/**
 * Lease / claim helpers for durable gov_paper_generation_jobs processing.
 */

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2.45.4";
import { refundCredits } from "./supabase.ts";

export const PAPER_JOB_LEASE_MS = 180_000;
export const PAPER_JOB_MAX_ATTEMPTS = 3;

export const PAPER_JOB_TERMINAL = new Set([
  "completed",
  "failed",
  "cancelled",
  "expired",
]);

export const PAPER_JOB_IN_FLIGHT = new Set([
  "queued",
  "retrieving_sources",
  "analyzing_pattern",
  "planning_blueprint",
  "selecting_questions",
  "generating_questions",
  "validating_questions",
  "checking_similarity",
  "assembling",
]);

export type ServiceDb = SupabaseClient;

export function newWorkerId(prefix = "worker"): string {
  return `${prefix}_${crypto.randomUUID().slice(0, 12)}`;
}

export function leaseExpiryIso(fromMs = Date.now(), leaseMs = PAPER_JOB_LEASE_MS): string {
  return new Date(fromMs + leaseMs).toISOString();
}

/** Idempotent status patch — never overwrites terminal rows. */
export async function setJobIfActive(
  db: ServiceDb,
  jobId: string,
  patch: Record<string, unknown>,
  opts?: { workerId?: string },
): Promise<boolean> {
  let q = db
    .from("gov_paper_generation_jobs")
    .update({ ...patch, updated_at: new Date().toISOString() })
    .eq("id", jobId)
    .filter("status", "not.in", `(${[...PAPER_JOB_TERMINAL].join(",")})`);

  if (opts?.workerId) {
    q = q.eq("worker_id", opts.workerId);
  }

  const { data, error } = await q.select("id").maybeSingle();
  if (error) {
    console.error("[govPaperJobLease] setJobIfActive:", error.message);
    return false;
  }
  return Boolean(data?.id);
}

export async function heartbeatJobLease(
  db: ServiceDb,
  jobId: string,
  workerId: string,
  leaseMs = PAPER_JOB_LEASE_MS,
): Promise<boolean> {
  const now = new Date().toISOString();
  const { data, error } = await db
    .from("gov_paper_generation_jobs")
    .update({
      heartbeat_at: now,
      lease_expires_at: leaseExpiryIso(Date.now(), leaseMs),
      updated_at: now,
    })
    .eq("id", jobId)
    .eq("worker_id", workerId)
    .filter("status", "not.in", `(${[...PAPER_JOB_TERMINAL].join(",")})`)
    .select("id, status")
    .maybeSingle();

  if (error) {
    console.error("[govPaperJobLease] heartbeat:", error.message);
    return false;
  }
  return Boolean(data?.id);
}

export async function isJobCancelled(db: ServiceDb, jobId: string): Promise<boolean> {
  const { data } = await db
    .from("gov_paper_generation_jobs")
    .select("status")
    .eq("id", jobId)
    .maybeSingle();
  return data?.status === "cancelled" || data?.status === "expired";
}

export type ClaimResult =
  | { ok: true; job: Record<string, unknown>; workerId: string; attemptCount: number }
  | { ok: false; reason: "not_found" | "not_claimable" | "max_attempts" | "error"; message?: string };

/**
 * Atomically claim a queued (or lease-expired in-flight) job.
 * Pass jobId to target a specific row; omit to claim the oldest claimable job.
 */
export async function claimPaperGenerationJob(
  db: ServiceDb,
  opts: {
    jobId?: string;
    workerId?: string;
    userId?: string;
    leaseMs?: number;
    maxAttempts?: number;
  } = {},
): Promise<ClaimResult> {
  const workerId = opts.workerId ?? newWorkerId("paper");
  const leaseMs = opts.leaseMs ?? PAPER_JOB_LEASE_MS;
  const maxAttempts = opts.maxAttempts ?? PAPER_JOB_MAX_ATTEMPTS;
  const nowIso = new Date().toISOString();

  // Auto-claim: in-flight only. Explicit jobId also allows retryable failed rows.
  const claimableStatuses = opts.jobId
    ? [...PAPER_JOB_IN_FLIGHT, "failed"]
    : [...PAPER_JOB_IN_FLIGHT];

  let pick = db
    .from("gov_paper_generation_jobs")
    .select(
      "id, user_id, exam_id, stage_id, pattern_version_id, syllabus_version_id, mode, language, request_json, status, progress_stage, attempt_count, retryable, credits_charged, random_seed, mock_test_id, generated_paper_id, lease_expires_at, worker_id, started_at",
    )
    .in("status", claimableStatuses)
    .eq("retryable", true)
    .or(`lease_expires_at.is.null,lease_expires_at.lt.${nowIso}`)
    .order("created_at", { ascending: true })
    .limit(1);

  if (opts.jobId) pick = pick.eq("id", opts.jobId);
  if (opts.userId) pick = pick.eq("user_id", opts.userId);

  const { data: candidates, error: pickErr } = await pick;
  if (pickErr) {
    return { ok: false, reason: "error", message: pickErr.message };
  }
  const candidate = Array.isArray(candidates) ? candidates[0] : candidates;
  if (!candidate?.id) {
    return { ok: false, reason: opts.jobId ? "not_found" : "not_claimable" };
  }

  const priorAttempts = Number(candidate.attempt_count) || 0;
  if (priorAttempts >= maxAttempts) {
    const creditsCharged = Math.max(0, Number(candidate.credits_charged) || 0);
    await db
      .from("gov_paper_generation_jobs")
      .update({
        status: "failed",
        progress_stage: "failed",
        retryable: false,
        error_code: "MAX_ATTEMPTS",
        error_message: `Exceeded max attempts (${maxAttempts})`,
        completed_at: nowIso,
        updated_at: nowIso,
        lease_expires_at: null,
        worker_id: null,
        credits_charged: 0,
      })
      .eq("id", candidate.id)
      .filter("status", "not.in", "(completed,cancelled,expired)");
    if (creditsCharged > 0 && candidate.user_id) {
      await refundCredits({
        userId: String(candidate.user_id),
        cost: creditsCharged,
        reason: "refund_paper_gen_max_attempts",
      }).catch(() => {});
    }
    return { ok: false, reason: "max_attempts" };
  }

  const nextAttempt = priorAttempts + 1;
  const leaseUntil = leaseExpiryIso(Date.now(), leaseMs);
  const resumeStatus =
    candidate.status === "queued" || candidate.status === "failed"
      ? "analyzing_pattern"
      : String(candidate.status);

  // Optimistic claim: only if still claimable (same lease window / still non-terminal).
  const { data: claimed, error: claimErr } = await db
    .from("gov_paper_generation_jobs")
    .update({
      worker_id: workerId,
      lease_expires_at: leaseUntil,
      heartbeat_at: nowIso,
      attempt_count: nextAttempt,
      status: resumeStatus,
      progress_stage: resumeStatus,
      started_at: candidate.started_at ?? nowIso,
      updated_at: nowIso,
      completed_at: null,
      error_code: null,
      error_message: null,
    })
    .eq("id", candidate.id)
    .eq("retryable", true)
    .in("status", claimableStatuses)
    .or(`lease_expires_at.is.null,lease_expires_at.lt.${nowIso}`)
    .select(
      "id, user_id, exam_id, stage_id, pattern_version_id, syllabus_version_id, mode, language, request_json, status, attempt_count, retryable, credits_charged, random_seed, mock_test_id, generated_paper_id, blueprint_json",
    )
    .maybeSingle();
  if (claimErr) {
    return { ok: false, reason: "error", message: claimErr.message };
  }
  if (!claimed?.id) {
    return { ok: false, reason: "not_claimable" };
  }

  return {
    ok: true,
    job: claimed as Record<string, unknown>,
    workerId,
    attemptCount: nextAttempt,
  };
}

/** Clear lease fields on terminal cancel / complete. */
export async function clearJobLease(
  db: ServiceDb,
  jobId: string,
  extra: Record<string, unknown> = {},
): Promise<void> {
  await db
    .from("gov_paper_generation_jobs")
    .update({
      ...extra,
      worker_id: null,
      lease_expires_at: null,
      updated_at: new Date().toISOString(),
    })
    .eq("id", jobId);
}

// supabase/functions/_shared/supabase.ts// sup// - Prevent empty/missing Supabase env usage
// - Provide safe credit deduction helpers
// - Provide best-effort idempotency support for financial/credit actions
// - Provide safe credit refund helper
//
// REQUIRED ENV:
// - SUPABASE_URL
// - SUPABASE_SERVICE_ROLE_KEY
// - SUPABASE_ANON_KEY
//
// IMPORTANT:
// The service role key bypasses RLS.
// Use createServiceClient() only inside trusted Edge Functions.

import {
  createClient,
  type SupabaseClient,
} from "https://esm.sh/@supabase/supabase-js@2.45.4";
import { classifyCreditFailure } from "./creditAuthority.ts";

export type CreditDeductionResult = {
  success: boolean;
  newBalance?: number;
  transactionId?: string;
  error?: string;
};

export type DeductCreditsAtomicInput = {
  userId: string;
  action: string;
  cost: number;
  sessionId?: string | null;
  idempotencyKey?: string | null;
  requestHash?: string | null;
};

export type DeductCreditsAtomicResult = {
  success: boolean;
  balanceAfter?: number;
  /** Spendable balance observed for this attempt (after success, or remaining on denial). */
  balance?: number;
  transactionId?: string;
  error?: string;
  code?: string;
  /** Optional cached business payload for full request replay (e.g. prep-tool AI result). */
  payload?: Record<string, unknown>;
};

export type RefundCreditsInput = {
  userId: string;
  cost: number;
  reason: string;
  sessionId?: string | null;
};

type IdempotencyRecord = {
  key: string;
  response: DeductCreditsAtomicResult;
  expires_at: string;
  metadata: Record<string, string>;
};

const IDEMPOTENCY_TABLE = "idempotency_log";
const IDEMPOTENCY_TTL_MS = 24 * 60 * 60 * 1000;

function getRequiredEnv(name: string): string {
  const value = Deno.env.get(name);

  if (!value || value.trim().length === 0) {
    throw new Error(`[supabase] Missing required environment variable: ${name}`);
  }

  return value.trim();
}

function isValidUuid(value: string): boolean {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(
    value
  );
}

function isValidIdempotencyKey(value: string): boolean {
  return /^[A-Za-z0-9._:-]{16,150}$/.test(value);
}

function normalizeAction(action: string): string {
  return action
    .trim()
    .replace(/[^A-Za-z0-9._:-]/g, "_")
    .slice(0, 100);
}

function normalizeReason(reason: string): string {
  return reason
    .trim()
    .replace(/[\u0000-\u001F\u007F]/g, "")
    .slice(0, 500);
}

function assertValidCreditInput(userId: string, action: string, amount: number): void {
  if (!userId || !isValidUuid(userId)) {
    throw new Error("Invalid userId.");
  }

  if (!action || action.trim().length === 0) {
    throw new Error("Missing credit action.");
  }

  if (!Number.isInteger(amount) || amount <= 0 || amount > 1_000_000) {
    throw new Error("Invalid credit amount.");
  }
}

/* -------------------------------------------------------------------------- */
/*                              SERVICE CLIENT                                 */
/* -------------------------------------------------------------------------- */

export function createServiceClient(): SupabaseClient {
  const url = getRequiredEnv("SUPABASE_URL");
  const key = getRequiredEnv("SUPABASE_SERVICE_ROLE_KEY");

  return createClient(url, key, {
    auth: {
      autoRefreshToken: false,
      persistSession: false,
      detectSessionInUrl: false,
    },
  });
}

/* -------------------------------------------------------------------------- */
/*                              USER CLIENT                                    */
/* -------------------------------------------------------------------------- */

/**
 * User-scoped client where RLS applies.
 *
 * Use when Postgres functions rely on auth.uid().
 */
export function createUserClient(accessToken: string): SupabaseClient {
  if (!accessToken || accessToken.trim().length === 0) {
    throw new Error("[supabase] Missing access token for user client.");
  }

  const url = getRequiredEnv("SUPABASE_URL");
  const anon = getRequiredEnv("SUPABASE_ANON_KEY");

  return createClient(url, anon, {
    global: {
      headers: {
        Authorization: `Bearer ${accessToken.trim()}`,
      },
    },
    auth: {
      autoRefreshToken: false,
      persistSession: false,
      detectSessionInUrl: false,
    },
  });
}

/* -------------------------------------------------------------------------- */
/*                              IDEMPOTENCY                                    */
/* -------------------------------------------------------------------------- */

/**
 * Best-effort idempotency lookup.
 *
 * If the table does not exist yet, this safely returns null.
 * Recommended table:
 *
 * idempotency_log:
 * - key text primary key
 * - response jsonb not null
 * - expires_at timestamptz not null
 * - created_at timestamptz default now()
 */
export async function getIdempotentResponse(
  db: SupabaseClient,
  key?: string | null,
  scope?: { userId: string; action: string; requestHash?: string | null }
): Promise<DeductCreditsAtomicResult | null> {
  if (!key) {
    return null;
  }

  // Invalid keys must not fail the credit path — treat as "no key" so callers retry safely.
  if (!isValidIdempotencyKey(key)) {
    console.warn("[credits] Ignoring invalid idempotency key shape.");
    return null;
  }

  try {
    const { data, error } = await db
      .from(IDEMPOTENCY_TABLE)
      .select("response, expires_at, metadata")
      .eq("key", key)
      .maybeSingle();

    if (error || !data) {
      return null;
    }

    const record = data as {
      response?: DeductCreditsAtomicResult;
      expires_at?: string;
    };

    if (!record.expires_at || new Date(record.expires_at).getTime() <= Date.now()) {
      return null;
    }

    if (scope) {
      const metadata = (data as { metadata?: Record<string, unknown> }).metadata;
      if (
        metadata?.user_id !== scope.userId ||
        metadata?.action !== normalizeAction(scope.action) ||
        (scope.requestHash && metadata?.request_hash !== scope.requestHash)
      ) {
        return null;
      }
    }

    // Never replay stored *failures* — allow a fresh deduction attempt.
    if (record.response && record.response.success === false) {
      return null;
    }

    return record.response ?? null;
  } catch {
    return null;
  }
}

export async function storeIdempotentResponse(
  db: SupabaseClient,
  key: string | null | undefined,
  response: DeductCreditsAtomicResult,
  scope?: { userId: string; action: string; requestHash?: string | null }
): Promise<void> {
  if (!key || !isValidIdempotencyKey(key)) {
    return;
  }

  const record: IdempotencyRecord = {
    key,
    response,
    expires_at: new Date(Date.now() + IDEMPOTENCY_TTL_MS).toISOString(),
    metadata: {
      ...(scope?.userId ? { user_id: scope.userId } : {}),
      ...(scope?.action ? { action: normalizeAction(scope.action) } : {}),
      ...(scope?.requestHash ? { request_hash: scope.requestHash } : {}),
    },
  };

  try {
    await db.from(IDEMPOTENCY_TABLE).upsert(record, {
      onConflict: "key",
    });
  } catch (error) {
    console.error(
      "[supabase] Failed to store idempotency response:",
      error instanceof Error ? error.message : String(error)
    );
  }
}

/* -------------------------------------------------------------------------- */
/*                              CREDIT SYSTEM                                  */
/* -------------------------------------------------------------------------- */

/**
 * Low-level hardened credit deduction.
 *
 * Uses the service-role transaction RPC when available. The RPC locks the
 * profile row and records the ledger entry in the same database transaction.
 */
export async function deductCredits(
  userId: string,
  action: string,
  amount: number
): Promise<CreditDeductionResult> {
  try {
    assertValidCreditInput(userId, action, amount);

    const normalizedAction = normalizeAction(action);
    const db = createServiceClient();
    const { data, error } = await db.rpc("deduct_credits_service", {
      p_user_id: userId,
      p_action: normalizedAction,
      p_cost: amount,
      p_session_id: null,
      p_idempotency_key: null,
      p_request_hash: null,
    });

    if (error || !data || typeof data !== "object") {
      return { success: false, error: "Credit deduction failed." };
    }

    const result = data as {
      success?: boolean;
      error?: string;
      new_balance?: number;
      transaction_id?: string;
    };
    if (!result.success) {
      return { success: false, error: result.error ?? "Credit deduction failed." };
    }
    if (!Number.isInteger(result.new_balance)) {
      return { success: false, error: "Credit deduction returned an invalid balance." };
    }
    return {
      success: true,
      newBalance: result.new_balance,
      transactionId:
        typeof result.transaction_id === "string" ? result.transaction_id : undefined,
    };
  } catch (error) {
    console.error(
      "[credits] Unexpected deduction error:",
      error instanceof Error ? error.message : String(error)
    );

    return {
      success: false,
      error: "Unexpected credit deduction failure.",
    };
  }
}

/**
 * High-level helper used by AI/session/payment functions.
 *
 * Adds optional:
 * - session_id attachment
 * - idempotency lookup/storage
 *
 * The service-role RPC owns the balance lock, ledger insert, and optional
 * idempotency record in one database transaction.
 */
export async function deductCreditsAtomic(
  input: DeductCreditsAtomicInput
): Promise<DeductCreditsAtomicResult> {
  const db = createServiceClient();

  const idempotentResponse = await getIdempotentResponse(db, input.idempotencyKey, {
    userId: input.userId,
    action: input.action,
    requestHash: input.requestHash,
  });

  if (idempotentResponse) {
    return idempotentResponse;
  }

  const rpcResult = await db.rpc("deduct_credits_service", {
    p_user_id: input.userId,
    p_action: normalizeAction(input.action),
    p_cost: input.cost,
    p_session_id: input.sessionId && isValidUuid(input.sessionId) ? input.sessionId : null,
    p_idempotency_key: input.idempotencyKey ?? null,
    p_request_hash: input.requestHash ?? null,
  });

  const rpcData = rpcResult.data as {
    success?: boolean;
    error?: string;
    code?: string;
    new_balance?: number;
    balance?: number;
    transaction_id?: string;
  } | null;

  if (rpcResult.error) {
    const unavailable = classifyCreditFailure(
      rpcResult.error.message ?? "Credit service unavailable.",
      "CREDIT_SERVICE_UNAVAILABLE",
    );
    return {
      success: false,
      error: "Credit service unavailable.",
      code: unavailable,
    };
  }

  const parsedBalance = Number(rpcData?.new_balance ?? rpcData?.balance);
  const balanceOk = Number.isFinite(parsedBalance);
  const result = {
    success: Boolean(rpcData?.success) && balanceOk,
    error: rpcData?.error,
    code: rpcData?.code,
    newBalance: parsedBalance,
    transactionId: rpcData?.transaction_id,
    remaining: Number.isFinite(Number(rpcData?.balance))
      ? Number(rpcData?.balance)
      : parsedBalance,
  };

  if (!result.success) {
    // Do not persist failed deductions — retries with the same Idempotency-Key
    // must be allowed (getIdempotentResponse also skips stored failures).
    const code = classifyCreditFailure(result.error, result.code);
    return {
      success: false,
      error: result.error ?? "Credit deduction failed.",
      code,
      balance: Number.isFinite(result.remaining) ? Math.max(0, Math.floor(result.remaining)) : undefined,
    };
  }

  let transactionId = result.transactionId;

  if (input.sessionId && !isValidUuid(input.sessionId)) {
    console.error("[credits] Invalid sessionId provided for credit transaction.");
  }

  if (input.sessionId && isValidUuid(input.sessionId)) {
    try {
      if (transactionId) {
        await db
          .from("credit_transactions")
          .update({
            session_id: input.sessionId,
          })
          .eq("id", transactionId);
      } else {
        const { data: lastTransaction } = await db
          .from("credit_transactions")
          .select("id")
          .eq("user_id", input.userId)
          .eq("action", "usage")
          .eq("balance_after", result.newBalance)
          .order("created_at", {
            ascending: false,
          })
          .limit(1)
          .maybeSingle();

        if (lastTransaction && typeof lastTransaction.id === "string") {
          transactionId = lastTransaction.id;

          await db
            .from("credit_transactions")
            .update({
              session_id: input.sessionId,
            })
            .eq("id", lastTransaction.id);
        }
      }
    } catch (error) {
      console.error(
        "[credits] Failed to attach session_id:",
        error instanceof Error ? error.message : String(error)
      );
    }
  }

  const success: DeductCreditsAtomicResult = {
    success: true,
    balanceAfter: result.newBalance,
    balance: result.newBalance,
    transactionId,
    code: "OK",
  };

  await storeIdempotentResponse(db, input.idempotencyKey, success, {
    userId: input.userId,
    action: input.action,
    requestHash: input.requestHash,
  });

  return success;
}

