/**
 * Best-effort credit refund helper.
 *
 * Prefer a Postgres RPC named refund_credits if available.
 * Falls back to guarded profile increment + transaction log.
 */
export async function refundCredits(
  input: RefundCreditsInput
): Promise<{ success: boolean; error?: string }> {
  if (!input.userId || !isValidUuid(input.userId)) {
    return {
      success: false,
      error: "Invalid userId.",
    };
  }

  if (!Number.isInteger(input.cost) || input.cost <= 0) {
    return {
      success: false,
      error: "Invalid refund amount.",
    };
  }

  const db = createServiceClient();
  const reason = normalizeReason(input.reason);

  try {
    const rpcResult = await db.rpc("refund_credits", {
      p_user_id: input.userId,
      p_cost: input.cost,
      p_reason: reason,
    });

    const result = rpcResult.data as { success?: boolean; error?: string } | null;
    if (!rpcResult.error && result?.success === true) {
      return {
        success: true,
      };
    }

    console.warn(
      "[credits] refund_credits RPC failed:",
      rpcResult.error?.message ?? result?.error ?? "unknown error"
    );
  } catch (error) {
    console.error(
      "[credits] Refund RPC failed:",
      error instanceof Error ? error.message : String(error)
    );
  }

  return { success: false, error: "Refund failed." };
}
//
// Shared Supabase utilities for Edge Functions.
//
// SECURITY PURPOSE:
// - Centralize Supabase service-role client creation
// - Centralize user-scoped client creation

/**
 * Server-authoritative credit denial classification.
 * Never map every deduction failure to PAYMENT_REQUIRED / INSUFFICIENT_CREDITS.
 */
import { getCorsHeaders } from "./cors.ts";

export type CreditErrorCode =
  | "INSUFFICIENT_CREDITS"
  | "CAPABILITY_REQUIRED"
  | "MAX_ATTEMPTS_REACHED"
  | "PAYMENT_REQUIRED"
  | "CREDIT_SERVICE_UNAVAILABLE"
  | "ACCOUNT_RESTRICTED"
  | "INVALID_OPERATION"
  | "PROVIDER_UNAVAILABLE"
  | "QUESTION_INVENTORY_INSUFFICIENT";

export type CreditDenialBody = {
  error: string;
  code: CreditErrorCode | string;
  balance?: number;
  cost?: number;
  required?: number;
  shortfall?: number;
  current?: number;
  limit?: number;
  resetAt?: string | null;
  available?: number;
  requested?: number;
};

function finiteInt(value: unknown): number | undefined {
  const n = Number(value);
  if (!Number.isFinite(n)) return undefined;
  return Math.max(0, Math.floor(n));
}

export function classifyCreditFailure(
  message: string | null | undefined,
  rpcCode?: string | null,
): CreditErrorCode {
  const code = String(rpcCode ?? "").trim().toUpperCase();
  const known: CreditErrorCode[] = [
    "INSUFFICIENT_CREDITS",
    "CAPABILITY_REQUIRED",
    "MAX_ATTEMPTS_REACHED",
    "PAYMENT_REQUIRED",
    "CREDIT_SERVICE_UNAVAILABLE",
    "ACCOUNT_RESTRICTED",
    "INVALID_OPERATION",
    "PROVIDER_UNAVAILABLE",
    "QUESTION_INVENTORY_INSUFFICIENT",
  ];
  if ((known as string[]).includes(code)) return code as CreditErrorCode;

  const msg = String(message ?? "").toLowerCase();
  if (!msg) return "CREDIT_SERVICE_UNAVAILABLE";
  if (
    msg.includes("insufficient credits") ||
    msg.includes("insufficient funds") ||
    msg.includes("no credits") ||
    msg.includes("out of credits")
  ) {
    return "INSUFFICIENT_CREDITS";
  }
  if (msg.includes("forbidden") || msg.includes("banned") || msg.includes("restricted")) {
    return "ACCOUNT_RESTRICTED";
  }
  if (msg.includes("profile not found")) return "ACCOUNT_RESTRICTED";
  if (msg.includes("invalid") || msg.includes("conflict")) return "INVALID_OPERATION";
  if (
    msg.includes("does not exist") ||
    msg.includes("could not find the function") ||
    msg.includes("unavailable") ||
    msg.includes("pgrst")
  ) {
    return "CREDIT_SERVICE_UNAVAILABLE";
  }
  return "CREDIT_SERVICE_UNAVAILABLE";
}

export function httpStatusForCreditCode(code: string): number {
  switch (code) {
    case "INSUFFICIENT_CREDITS":
    case "PAYMENT_REQUIRED":
      return 402;
    case "CAPABILITY_REQUIRED":
    case "ACCOUNT_RESTRICTED":
      return 403;
    case "MAX_ATTEMPTS_REACHED":
      return 429;
    case "QUESTION_INVENTORY_INSUFFICIENT":
      return 409;
    case "INVALID_OPERATION":
      return 400;
    case "PROVIDER_UNAVAILABLE":
    case "CREDIT_SERVICE_UNAVAILABLE":
      return 503;
    default:
      return 500;
  }
}

export function safeCreditMessage(code: string, fallback?: string): string {
  switch (code) {
    case "INSUFFICIENT_CREDITS":
      return fallback && /need|have|available/i.test(fallback)
        ? fallback
        : "Insufficient credits.";
    case "PAYMENT_REQUIRED":
      return "Payment is required to continue.";
    case "CAPABILITY_REQUIRED":
      return "This feature requires a supported plan.";
    case "MAX_ATTEMPTS_REACHED":
      return "You have reached the attempt limit for this plan.";
    case "ACCOUNT_RESTRICTED":
      return "This account cannot perform that action.";
    case "INVALID_OPERATION":
      return "This credit operation is not valid.";
    case "CREDIT_SERVICE_UNAVAILABLE":
      return "Credits couldn't be verified right now. Please try again.";
    case "PROVIDER_UNAVAILABLE":
      return "The exam generation service is temporarily unavailable. Please try again.";
    case "QUESTION_INVENTORY_INSUFFICIENT":
      return "Not enough approved questions are available for this configuration.";
    default:
      return "Credit operation failed.";
  }
}

export function buildCreditDenialBody(
  result: { error?: string; code?: string; balance?: number },
  cost: number,
): CreditDenialBody {
  const code = classifyCreditFailure(result.error, result.code);
  const balance = finiteInt(result.balance);
  const required = finiteInt(cost);
  const shortfall =
    typeof balance === "number" && typeof required === "number"
      ? Math.max(0, required - balance)
      : undefined;
  const body: CreditDenialBody = {
    error: safeCreditMessage(
      code,
      typeof required === "number" && typeof balance === "number" && code === "INSUFFICIENT_CREDITS"
        ? `You need ${required} credits, but only ${balance} are available.`
        : result.error,
    ),
    code,
  };
  if (typeof balance === "number") body.balance = balance;
  if (typeof required === "number") {
    body.cost = required;
    body.required = required;
  }
  if (typeof shortfall === "number") body.shortfall = shortfall;
  return body;
}

export function creditDenialResponse(
  req: Request,
  result: { error?: string; code?: string; balance?: number },
  cost: number,
): Response {
  const body = buildCreditDenialBody(result, cost);
  return new Response(JSON.stringify(body), {
    status: httpStatusForCreditCode(body.code),
    headers: { ...getCorsHeaders(req), "Content-Type": "application/json" },
  });
}

// supabase/functions/_shared/cors.ts
//
// Shared CORS contract for every browser-facing Supabase Edge Function.
//
// SECURITY PURPOSE:
// - Allow only trusted browser origins (never wildcard + credentials)
// - Handle OPTIONS before authentication / business logic
// - Attach CORS + correlation IDs to every response path, including errors
// - Keep CORS as a browser access control, not an authentication substitute
//
// HOW TO CONFIGURE:
//
// ALLOWED_ORIGINS — comma-separated explicit origins
//   https://trycareerpilot.com,https://trycareerpilot.com,https://www.trycareerpilot.com
//
// ALLOW_LOCALHOST_ORIGINS — "true" (default) or "false"
// ALLOW_PREVIEW_ORIGINS — "true" (default) or "false" (Lovable preview hosts)
// ALLOW_ELECTRON_NULL_ORIGIN — "true" (default) or "false" (file:// Electron)
// APP_ENV / ENVIRONMENT / DENO_ENV — production vs non-production labels

export type CorsEnvReader = {
  get(key: string): string | undefined;
};

const DEFAULT_ENV: CorsEnvReader = {
  get(key: string): string | undefined {
    try {
      const deno = (globalThis as {
        Deno?: { env?: { get?: (name: string) => string | undefined } };
      }).Deno;
      return deno?.env?.get?.(key);
    } catch {
      return undefined;
    }
  },
};

let envReader: CorsEnvReader = DEFAULT_ENV;
let cachedOrigins: Set<string> | null = null;
let cachedOriginKey: string | null = null;
let serveGuardInstalled = false;

const LOCAL_DEV_ORIGINS = [
  "http://localhost:3000",
  "http://localhost:4173",
  "http://localhost:5000",
  "http://localhost:5001",
  "http://localhost:5002",
  "http://localhost:5173",
  "http://127.0.0.1:3000",
  "http://127.0.0.1:4173",
  "http://127.0.0.1:5000",
  "http://127.0.0.1:5001",
  "http://127.0.0.1:5002",
  "http://127.0.0.1:5173",
];

/** Known production browser origins — merged even if ALLOWED_ORIGINS secret is missing. */
const KNOWN_PRODUCTION_ORIGINS = [
  "https://trycareerpilot.com",
  "https://trycareerpilot.com",
  "https://www.trycareerpilot.com",
  "https://trycareerpilot.com",
];

/** Custom-protocol Electron shells (file:// uses Origin: null, handled separately). */
const KNOWN_ELECTRON_ORIGINS = [
  "app://.",
  "clarify-coach://.",
];

const PREVIEW_HOST_PATTERNS: RegExp[] = [
  /\.lovable\.app$/i,
  /\.lovable\.dev$/i,
  /\.lovableproject\.com$/i,
];

const ALLOWED_METHODS = [
  "GET",
  "POST",
  "PUT",
  "PATCH",
  "DELETE",
  "OPTIONS",
  "HEAD",
].join(", ");

const ALLOWED_HEADERS = [
  "authorization",
  "apikey",
  "content-type",
  "x-client-info",
  "x-app-name",
  "x-app-version",
  "x-csrf-token",
  "idempotency-key",
  "x-idempotency-key",
  "stripe-signature",
  "x-request-id",
  "x-correlation-id",
  "x-ai-training-consent",
].join(", ");

const EXPOSE_HEADERS = [
  "x-request-id",
  "x-correlation-id",
  "retry-after",
  "x-ratelimit-limit",
  "x-ratelimit-remaining",
  "x-ratelimit-reset",
].join(", ");

function readEnv(key: string): string {
  return (envReader.get(key) ?? "").trim();
}

function envFlag(key: string, defaultValue: boolean): boolean {
  const raw = readEnv(key).toLowerCase();
  if (!raw) return defaultValue;
  if (["1", "true", "yes", "on"].includes(raw)) return true;
  if (["0", "false", "no", "off"].includes(raw)) return false;
  return defaultValue;
}

function isProductionEnvironment(): boolean {
  const appEnv = readEnv("APP_ENV").toLowerCase();
  const environment = readEnv("ENVIRONMENT").toLowerCase();
  const denoEnv = readEnv("DENO_ENV").toLowerCase();

  const nonProdLabels = ["development", "dev", "local", "preview", "staging", "stage", "test"];
  if (
    nonProdLabels.includes(appEnv) ||
    nonProdLabels.includes(environment) ||
    ["development", "dev", "local", "test"].includes(denoEnv)
  ) {
    return false;
  }
  if (
    appEnv === "production" ||
    appEnv === "prod" ||
    environment === "production" ||
    environment === "prod" ||
    denoEnv === "production"
  ) {
    return true;
  }

  // Default fail-closed when unset (typical Supabase Edge runtime).
  return true;
}

function isValidOrigin(origin: string): boolean {
  try {
    const url = new URL(origin);
    return url.protocol === "http:" || url.protocol === "https:";
  } catch {
    return false;
  }
}

function normalizeOrigin(origin: string): string | null {
  const trimmed = origin.trim();
  if (!trimmed || !isValidOrigin(trimmed)) return null;
  try {
    return new URL(trimmed).origin;
  } catch {
    return null;
  }
}

function addOriginIfValid(origins: Set<string>, origin: string): void {
  const normalized = normalizeOrigin(origin);
  if (normalized) origins.add(normalized);
}

function originCacheKey(): string {
  return [
    readEnv("ALLOWED_ORIGINS"),
    readEnv("ALLOW_LOCALHOST_ORIGINS"),
    readEnv("ALLOW_PREVIEW_ORIGINS"),
    readEnv("ALLOW_ELECTRON_NULL_ORIGIN"),
    readEnv("APP_ENV"),
    readEnv("ENVIRONMENT"),
    readEnv("DENO_ENV"),
  ].join("|");
}

function getAllowedOrigins(): Set<string> {
  const key = originCacheKey();
  if (cachedOrigins && cachedOriginKey === key) {
    return cachedOrigins;
  }

  const origins = new Set<string>();
  const isProduction = isProductionEnvironment();

  if (envFlag("ALLOW_LOCALHOST_ORIGINS", true)) {
    for (const origin of LOCAL_DEV_ORIGINS) {
      addOriginIfValid(origins, origin);
    }
  }

  if (isProduction) {
    for (const origin of KNOWN_PRODUCTION_ORIGINS) {
      addOriginIfValid(origins, origin);
    }
  }

  for (const origin of KNOWN_ELECTRON_ORIGINS) {
    origins.add(origin);
  }

  const configured = readEnv("ALLOWED_ORIGINS");
  if (configured.length > 0) {
    for (const origin of configured.split(",")) {
      addOriginIfValid(origins, origin);
    }
  } else if (isProduction) {
    console.error(
      "[cors] ALLOWED_ORIGINS secret not set in production. " +
        "Non-localhost browser origins outside the known production list will be rejected. " +
        "Set ALLOWED_ORIGINS in Supabase Dashboard → Edge Functions → Secrets.",
    );
  } else {
    console.warn(
      "[cors] ALLOWED_ORIGINS not set — only localhost / configured preview origins are allowed.",
    );
  }

  cachedOrigins = origins;
  cachedOriginKey = key;
  return origins;
}

function getRequestOrigin(req: Request): string | null {
  const rawOrigin = req.headers.get("origin") ?? req.headers.get("Origin");
  if (!rawOrigin) return null;
  if (rawOrigin.trim() === "null") return "null";
  return normalizeOrigin(rawOrigin);
}

function isPreviewOrigin(origin: string): boolean {
  if (!envFlag("ALLOW_PREVIEW_ORIGINS", true)) return false;
  try {
    const { protocol, hostname } = new URL(origin);
    if (protocol !== "https:") return false;
    return PREVIEW_HOST_PATTERNS.some((re) => re.test(hostname));
  } catch {
    return false;
  }
}

function isOriginAllowedForCors(requestOrigin: string | null): boolean {
  if (!requestOrigin) return true;
  if (requestOrigin === "null") {
    return envFlag("ALLOW_ELECTRON_NULL_ORIGIN", true);
  }
  if (getAllowedOrigins().has(requestOrigin)) return true;
  if (isPreviewOrigin(requestOrigin)) return true;
  return false;
}

export function isOriginAllowed(req: Request): boolean {
  return isOriginAllowedForCors(getRequestOrigin(req));
}

export function resolveCorrelationId(req: Request): string {
  const fromHeader =
    req.headers.get("x-request-id")?.trim() ||
    req.headers.get("x-correlation-id")?.trim();
  if (fromHeader && fromHeader.length > 0 && fromHeader.length <= 128) {
    return fromHeader;
  }
  try {
    return crypto.randomUUID();
  } catch {
    return `req_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 10)}`;
  }
}

export function functionNameFromRequest(req: Request): string {
  try {
    const parts = new URL(req.url).pathname.split("/").filter(Boolean);
    return parts[parts.length - 1] || "edge-function";
  } catch {
    return "edge-function";
  }
}

/**
 * Returns CORS headers for a given request.
 * Credentialed requests never receive Access-Control-Allow-Origin: *.
 */
export function getCorsHeaders(req: Request): Record<string, string> {
  const requestOrigin = getRequestOrigin(req);

  const headers: Record<string, string> = {
    "Access-Control-Allow-Methods": ALLOWED_METHODS,
    "Access-Control-Allow-Headers": ALLOWED_HEADERS,
    "Access-Control-Expose-Headers": EXPOSE_HEADERS,
    "Access-Control-Max-Age": "86400",
    Vary: "Origin",
  };

  if (requestOrigin === "null" && isOriginAllowedForCors("null")) {
    headers["Access-Control-Allow-Origin"] = "null";
  } else if (requestOrigin && isOriginAllowedForCors(requestOrigin)) {
    headers["Access-Control-Allow-Origin"] = requestOrigin;
    headers["Access-Control-Allow-Credentials"] = "true";
  }

  if (requestOrigin && !isOriginAllowedForCors(requestOrigin)) {
    console.warn("[cors] Rejected origin:", requestOrigin);
  }

  return headers;
}

/**
 * Handles CORS preflight OPTIONS requests.
 *
 * Usage:
 *
 * const cors = handleCors(req);
 * if (cors) return cors;
 */
export function handleCors(req: Request): Response | null {
  if (req.method.toUpperCase() !== "OPTIONS") {
    return null;
  }

  const requestOrigin = getRequestOrigin(req);

  if (!requestOrigin) {
    return new Response(null, {
      status: 204,
      headers: getCorsHeaders(req),
    });
  }

  if (!isOriginAllowedForCors(requestOrigin)) {
    console.warn("[cors] Preflight rejected for origin:", requestOrigin);
    return new Response(
      JSON.stringify({
        success: false,
        error: "Origin not allowed.",
        code: "ORIGIN_NOT_ALLOWED",
      }),
      {
        status: 403,
        headers: {
          "Content-Type": "application/json",
          "Cache-Control": "no-store",
          Vary: "Origin",
        },
      },
    );
  }

  return new Response(null, {
    status: 204,
    headers: getCorsHeaders(req),
  });
}

function mergeHeaders(target: Headers, source: Record<string, string>): void {
  for (const [key, value] of Object.entries(source)) {
    target.set(key, value);
  }
}

/**
 * Adds CORS, security, and correlation headers to an existing response.
 * Safe to call more than once.
 */
export function applyCors(
  req: Request,
  response: Response,
  correlationId?: string,
): Response {
  const headers = new Headers(response.headers);
  mergeHeaders(headers, getCorsHeaders(req));

  const cid = correlationId ?? resolveCorrelationId(req);
  headers.set("x-request-id", headers.get("x-request-id") || cid);
  headers.set("x-correlation-id", headers.get("x-correlation-id") || cid);
  headers.set("X-Content-Type-Options", "nosniff");
  headers.set("Cache-Control", headers.get("Cache-Control") ?? "no-store");

  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

/**
 * Adds CORS headers to an existing response.
 */
export function withCorsHeaders(req: Request, response: Response): Response {
  return applyCors(req, response);
}

export function securityHeaders(origin?: string): Record<string, string> {
  const headers: Record<string, string> = {
    "X-Content-Type-Options": "nosniff",
    "X-Frame-Options": "DENY",
    "X-XSS-Protection": "0",
    "Referrer-Policy": "strict-origin-when-cross-origin",
    "Permissions-Policy": "camera=(), microphone=(self), geolocation=()",
    "Strict-Transport-Security": "max-age=63072000; includeSubDomains; preload",
  };

  if (origin && isOriginAllowedForCors(origin)) {
    headers["Access-Control-Allow-Origin"] = origin;
    headers["Access-Control-Allow-Headers"] = ALLOWED_HEADERS;
    headers["Access-Control-Allow-Methods"] = ALLOWED_METHODS;
    headers["Access-Control-Expose-Headers"] = EXPOSE_HEADERS;
    headers["Access-Control-Max-Age"] = "86400";
    if (origin !== "null") {
      headers["Access-Control-Allow-Credentials"] = "true";
    }
  }

  return headers;
}

export function withSecurityHeaders(req: Request, response: Response): Response {
  const wrapped = applyCors(req, response);
  const headers = new Headers(wrapped.headers);
  const extra = securityHeaders(getRequestOrigin(req) ?? undefined);
  mergeHeaders(headers, extra);
  headers.set("Vary", "Origin");
  return new Response(wrapped.body, {
    status: wrapped.status,
    statusText: wrapped.statusText,
    headers,
  });
}

export function corsJson(
  req: Request,
  status: number,
  body: unknown,
  extraHeaders: Record<string, string> = {},
): Response {
  const correlationId = resolveCorrelationId(req);
  return applyCors(
    req,
    new Response(JSON.stringify(body), {
      status,
      headers: {
        "Content-Type": "application/json",
        "Cache-Control": "no-store",
        ...extraHeaders,
      },
    }),
    correlationId,
  );
}

export function corsSuccess(
  req: Request,
  data: unknown,
  status = 200,
): Response {
  const correlationId = resolveCorrelationId(req);
  return corsJson(req, status, {
    success: true,
    data,
    correlation_id: correlationId,
    correlationId,
  });
}

export function corsError(
  req: Request,
  status: number,
  code: string,
  message: string,
): Response {
  const correlationId = resolveCorrelationId(req);
  return corsJson(req, status, {
    success: false,
    error: message,
    code,
    correlation_id: correlationId,
    correlationId,
  });
}

export function unexpectedErrorResponse(
  req: Request,
  functionName: string,
  error: unknown,
): Response {
  const correlationId = resolveCorrelationId(req);
  const err = error instanceof Error ? error : new Error(String(error));
  console.error(
    JSON.stringify({
      level: "error",
      functionName,
      correlationId,
      name: err.name,
      message: err.message,
    }),
  );

  const looksLikeInfra =
    /fetch failed|network|timeout|temporar|unavailable|ECONNREFUSED|503|502/i.test(
      err.message,
    );

  return corsError(
    req,
    looksLikeInfra ? 503 : 500,
    looksLikeInfra ? "SERVICE_UNAVAILABLE" : "INTERNAL_ERROR",
    looksLikeInfra
      ? "The service is temporarily unavailable. Please try again."
      : "Something went wrong. Please try again.",
  );
}

export function withBrowserCors(
  functionName: string,
  handler: (req: Request) => Promise<Response> | Response,
): (req: Request) => Promise<Response> {
  return async (req: Request): Promise<Response> => {
    const correlationId = resolveCorrelationId(req);
    const name = functionName || functionNameFromRequest(req);
    try {
      const preflight = handleCors(req);
      if (preflight) {
        return applyCors(req, preflight, correlationId);
      }
      const response = await handler(req);
      return applyCors(req, response, correlationId);
    } catch (error) {
      if (error instanceof Response) {
        return applyCors(req, error, correlationId);
      }
      return unexpectedErrorResponse(req, name, error);
    }
  };
}

type ServeHandler = (req: Request, info?: unknown) => Response | Promise<Response>;

function wrapServeHandler(handler: ServeHandler): ServeHandler {
  const wrapped = withBrowserCors("edge-function", (req) => handler(req));
  return (req: Request, _info?: unknown) => wrapped(req);
}

/**
 * Wraps Deno.serve so every Edge Function that imports this module gets the
 * shared CORS contract, including error / rate-limit / thrown-exception paths.
 */
export function installDenoServeCorsGuard(): void {
  if (serveGuardInstalled) return;
  const deno = (globalThis as {
    Deno?: {
      serve?: ((...args: unknown[]) => unknown) & { __clarifyCorsWrapped?: boolean };
    };
  }).Deno;
  if (!deno || typeof deno.serve !== "function") return;
  if (deno.serve.__clarifyCorsWrapped) {
    serveGuardInstalled = true;
    return;
  }

  const originalServe = deno.serve.bind(deno) as (...args: unknown[]) => unknown;
  const wrappedServe = ((...args: unknown[]) => {
    if (typeof args[0] === "function") {
      return originalServe(wrapServeHandler(args[0] as ServeHandler));
    }
    if (args.length >= 2 && typeof args[1] === "function") {
      return originalServe(args[0], wrapServeHandler(args[1] as ServeHandler));
    }
    return originalServe(...args);
  }) as typeof deno.serve;
  wrappedServe.__clarifyCorsWrapped = true;
  deno.serve = wrappedServe;
  serveGuardInstalled = true;
}

