/**
 * Flattens `gov_exam_syllabus_versions.topics_json` (`[{ section, topics[] }]`) into a
 * readable topic list for AI prompting. Returns `[]` when no approved syllabus exists.
 */
export async function loadSyllabusTopics(
  db: ServiceDb,
  syllabusVersionId: string | null | undefined,
): Promise<string[]> {
  if (!syllabusVersionId) return [];
  const { data, error } = await db
    .from("gov_exam_syllabus_versions")
    .select("topics_json")
    .eq("id", syllabusVersionId)
    .maybeSingle();
  if (error || !data) return [];

  const raw = (data as { topics_json?: unknown }).topics_json;
  const collected: string[] = [];

  const pushTopic = (value: unknown) => {
    const text = String(value ?? "")
      .replace(/[_-]+/g, " ")
      .replace(/\s+/g, " ")
      .trim();
    if (text) collected.push(text);
  };

  if (Array.isArray(raw)) {
    for (const entry of raw) {
      const topics = (entry as { topics?: unknown })?.topics;
      if (Array.isArray(topics)) topics.forEach(pushTopic);
    }
  } else if (raw && typeof raw === "object") {
    for (const topics of Object.values(raw as Record<string, unknown>)) {
      if (Array.isArray(topics)) topics.forEach(pushTopic);
    }
  }

  return [...new Set(collected)];
}

export type AssemblyResult =
  | {
    ok: true;
    status: "completed";
    mockTestId: string;
    paperId: string;
    questionCount: number;
    paperClass: string;
    disclaimer: string;
    patternVersion: string | null;
    syllabusVersion: string | null;
  }
  | {
    ok: false;
    status: "failed" | "cancelled";
    errorCode: string;
    error: string;
    httpStatus?: number;
    available?: number;
    required?: number;
  };

type JobRow = {
  id: string;
  user_id: string;
  exam_id: string;
  stage_id: string | null;
  pattern_version_id: string | null;
  syllabus_version_id: string | null;
  mode: string;
  language: string;
  request_json: Record<string, unknown> | null;
  credits_charged: number;
  random_seed: string | null;
  mock_test_id: string | null;
  generated_paper_id: string | null;
};

async function stage(
  db: ServiceDb,
  jobId: string,
  workerId: string,
  status: string,
  extra: Record<string, unknown> = {},
): Promise<"ok" | "cancelled" | "lost_lease"> {
  if (await isJobCancelled(db, jobId)) return "cancelled";
  const beat = await heartbeatJobLease(db, jobId, workerId);
  if (!beat) {
    // Lease lost or job terminal — re-check cancel
    if (await isJobCancelled(db, jobId)) return "cancelled";
    return "lost_lease";
  }
  const ok = await setJobIfActive(
    db,
    jobId,
    { status, progress_stage: status, ...extra },
    { workerId },
  );
  if (!ok) {
    if (await isJobCancelled(db, jobId)) return "cancelled";
    return "lost_lease";
  }
  return "ok";
}

async function failJob(
  db: ServiceDb,
  job: JobRow,
  workerId: string,
  errorCode: string,
  errorMessage: string,
  retryable: boolean,
  extra: Record<string, unknown> = {},
): Promise<void> {
  // Retryable: re-queue with cleared lease so another worker can claim.
  // Terminal: mark failed, refund credits, stop further claims.
  if (retryable) {
    await setJobIfActive(
      db,
      job.id,
      {
        status: "queued",
        progress_stage: "queued",
        error_code: errorCode,
        error_message: errorMessage,
        retryable: true,
        completed_at: null,
        worker_id: null,
        lease_expires_at: null,
        ...extra,
      },
      { workerId },
    );
    return;
  }

  await setJobIfActive(
    db,
    job.id,
    {
      status: "failed",
      progress_stage: "failed",
      error_code: errorCode,
      error_message: errorMessage,
      retryable: false,
      completed_at: new Date().toISOString(),
      worker_id: null,
      lease_expires_at: null,
      ...extra,
    },
    { workerId },
  );
  const cost = Math.max(0, Number(job.credits_charged) || 0);
  if (cost > 0) {
    await refundCredits({
      userId: job.user_id,
      cost,
      reason: `refund_paper_gen_${errorCode.toLowerCase()}`,
    }).catch(() => {});
    await clearJobLease(db, job.id, { credits_charged: 0 });
  }
}

/**
 * Run assembly for an already-claimed job (worker_id + lease held).
 * Idempotent: if mock_test_id / generated_paper_id already set, marks completed.
 */
export async function assembleClaimedPaperJob(
  db: ServiceDb,
  jobInput: Record<string, unknown>,
  workerId: string,
): Promise<AssemblyResult> {
  const job: JobRow = {
    id: String(jobInput.id),
    user_id: String(jobInput.user_id),
    exam_id: String(jobInput.exam_id),
    stage_id: (jobInput.stage_id as string | null) ?? null,
    pattern_version_id: (jobInput.pattern_version_id as string | null) ?? null,
    syllabus_version_id: (jobInput.syllabus_version_id as string | null) ?? null,
    mode: String(jobInput.mode ?? "custom_mock"),
    language: String(jobInput.language ?? "en"),
    request_json: (jobInput.request_json as Record<string, unknown> | null) ?? {},
    credits_charged: Number(jobInput.credits_charged) || 0,
    random_seed: (jobInput.random_seed as string | null) ?? null,
    mock_test_id: (jobInput.mock_test_id as string | null) ?? null,
    generated_paper_id: (jobInput.generated_paper_id as string | null) ?? null,
  };

  // Already assembled — idempotent complete
  if (job.mock_test_id && job.generated_paper_id) {
    await setJobIfActive(
      db,
      job.id,
      {
        status: "completed",
        progress_stage: "completed",
        completed_at: new Date().toISOString(),
        worker_id: null,
        lease_expires_at: null,
        retryable: false,
      },
      { workerId },
    );
    return {
      ok: true,
      status: "completed",
      mockTestId: job.mock_test_id,
      paperId: job.generated_paper_id,
      questionCount: 0,
      paperClass: "custom_practice",
      disclaimer: "",
      patternVersion: null,
      syllabusVersion: null,
    };
  }

  const req = job.request_json ?? {};
  const sourceYears = Array.isArray(req.sourceYears)
    ? (req.sourceYears as unknown[])
      .map((y) => Number(y))
      .filter((y) => Number.isFinite(y) && y >= 1990 && y <= 2100)
      .slice(0, 20)
    : [2024, 2023, 2022];

  const questionCountRaw = Number(req.questionCount);
  const questionCount = Number.isFinite(questionCountRaw)
    ? Math.min(200, Math.max(5, Math.floor(questionCountRaw)))
    : null;

  const durationRaw = Number(req.durationMinutes);
  const durationMinutes = Number.isFinite(durationRaw)
    ? Math.min(360, Math.max(5, Math.floor(durationRaw)))
    : null;

  const randomSeed = String(job.random_seed ?? job.id);
  const mode = (
    ["official_previous", "generated_mock", "custom_mock", "adaptive"].includes(job.mode)
      ? job.mode
      : "custom_mock"
  ) as "official_previous" | "generated_mock" | "custom_mock" | "adaptive";

  try {
    let st = await stage(db, job.id, workerId, "analyzing_pattern");
    if (st === "cancelled") {
      return { ok: false, status: "cancelled", errorCode: "CANCELLED", error: "Cancelled" };
    }
    if (st === "lost_lease") {
      return { ok: false, status: "failed", errorCode: "LEASE_LOST", error: "Lost job lease", httpStatus: 409 };
    }

    const { data: exam, error: examErr } = await db
      .from("gov_exams")
      .select("id, code, name, legacy_exam_type, review_state, is_public")
      .eq("id", job.exam_id)
      .maybeSingle();

    if (examErr || !exam) {
      await failJob(db, job, workerId, "EXAM_NOT_FOUND", "Exam not found", false);
      return { ok: false, status: "failed", errorCode: "EXAM_NOT_FOUND", error: "Exam not found", httpStatus: 404 };
    }

    st = await stage(db, job.id, workerId, "planning_blueprint");
    if (st === "cancelled") {
      return { ok: false, status: "cancelled", errorCode: "CANCELLED", error: "Cancelled" };
    }
    if (st === "lost_lease") {
      return { ok: false, status: "failed", errorCode: "LEASE_LOST", error: "Lost job lease", httpStatus: 409 };
    }

    let pattern: Record<string, unknown> | null = null;
    if (job.pattern_version_id) {
      const { data } = await db
        .from("gov_exam_pattern_versions")
        .select("*")
        .eq("id", job.pattern_version_id)
        .maybeSingle();
      pattern = data;
    }
    if (!pattern && job.stage_id) {
      const { data } = await db
        .from("gov_exam_pattern_versions")
        .select("*")
        .eq("exam_id", job.exam_id)
        .eq("stage_id", job.stage_id)
        .eq("review_state", "approved")
        .order("effective_date", { ascending: false })
        .limit(1)
        .maybeSingle();
      pattern = data;
    }
    if (!pattern) {
      await failJob(db, job, workerId, "PATTERN_NOT_AVAILABLE", "Approved pattern not available", false);
      return {
        ok: false,
        status: "failed",
        errorCode: "PATTERN_NOT_AVAILABLE",
        error: "Approved pattern not available",
        httpStatus: 409,
      };
    }

    const langs: string[] = Array.isArray(pattern.languages) ? pattern.languages as string[] : ["en"];

    const { data: sectionsRows } = await db
      .from("gov_exam_sections")
      .select("code, name, question_count, marks, sort_order")
      .eq("pattern_version_id", pattern.id)
      .order("sort_order", { ascending: true });

    const sections: PatternSection[] = (sectionsRows ?? []).map((s) => ({
      code: s.code,
      name: s.name,
      question_count: s.question_count,
      marks: Number(s.marks),
    }));

    if (sections.length === 0) {
      await failJob(db, job, workerId, "PATTERN_NOT_AVAILABLE", "Pattern sections missing", false);
      return {
        ok: false,
        status: "failed",
        errorCode: "PATTERN_NOT_AVAILABLE",
        error: "Pattern sections missing",
        httpStatus: 409,
      };
    }

    let syllabus: { id: string; version: string | null } | null = null;
    if (job.syllabus_version_id) {
      const { data } = await db
        .from("gov_exam_syllabus_versions")
        .select("id, version")
        .eq("id", job.syllabus_version_id)
        .maybeSingle();
      syllabus = data;
    } else if (job.stage_id) {
      const { data } = await db
        .from("gov_exam_syllabus_versions")
        .select("id, version")
        .eq("exam_id", job.exam_id)
        .eq("stage_id", job.stage_id)
        .eq("review_state", "approved")
        .order("effective_date", { ascending: false })
        .limit(1)
        .maybeSingle();
      syllabus = data;
    }

    const blueprint = buildBlueprint({
      examId: job.exam_id,
      examCode: exam.code,
      stageId: job.stage_id ?? "",
      pattern: {
        id: pattern.id as string,
        version: pattern.version as string,
        total_questions: pattern.total_questions as number,
        total_marks: Number(pattern.total_marks),
        duration_minutes: pattern.duration_minutes as number,
        negative_mark: Number(pattern.negative_mark),
        marks_per_question: Number(pattern.marks_per_question),
        languages: langs,
        sections,
      },
      syllabusVersionId: syllabus?.id ?? null,
      syllabusVersion: syllabus?.version ?? null,
      language: job.language,
      sourceYears,
      mode,
      randomSeed,
      customQuestionCount: questionCount,
      customDuration: durationMinutes,
    });

    const hard = validateBlueprintHardConstraints(blueprint);
    if (!hard.ok) {
      await failJob(
        db,
        job,
        workerId,
        "BLUEPRINT_INVALID",
        hard.errors.join("; "),
        false,
        { blueprint_json: blueprint },
      );
      return {
        ok: false,
        status: "failed",
        errorCode: "BLUEPRINT_INVALID",
        error: hard.errors.join("; "),
        httpStatus: 422,
      };
    }

    st = await stage(db, job.id, workerId, "selecting_questions", { blueprint_json: blueprint });
    if (st === "cancelled") {
      return { ok: false, status: "cancelled", errorCode: "CANCELLED", error: "Cancelled" };
    }
    if (st === "lost_lease") {
      return { ok: false, status: "failed", errorCode: "LEASE_LOST", error: "Lost job lease", httpStatus: 409 };
    }

    const examTypeKeys = examBankTypeKeys({
      code: exam.code as string | null,
      name: exam.name as string | null,
      legacy_exam_type: exam.legacy_exam_type as string | null,
    });
    const insertExamType =
      (exam.legacy_exam_type as string | null) ||
      mapExamType(String(exam.code ?? exam.name ?? ""));

    const PYP_SOURCES = ["OFFICIAL_PYP", "Previous Year Paper", "PYP", "previous_year"];

    let bankRows: GapFillRow[] = [];
    if (examTypeKeys.length > 0) {
      // Public PYP rows are practice-ready even when is_verified is still false.
      // Requiring verified-only dropped ~1000 previous-year questions and forced AI fill.
      let bankQuery = db
        .from("questions")
        .select(
          "id, question_text, options, correct_answer, subject, topic, difficulty, source, source_year, is_public, is_verified",
        )
        .eq("is_public", true)
        .in("exam_type", examTypeKeys)
        .limit(2000);
      if (mode === "official_previous") {
        bankQuery = bankQuery.in("source", PYP_SOURCES);
      }
      const { data, error: bankErr } = await bankQuery;
      if (bankErr) {
        throw new Error(bankErr.message);
      }
      bankRows = (data ?? []) as GapFillRow[];
    }

    let candidates = seededShuffle(bankRows, randomSeed);

    if (mode === "adaptive") {
      try {
        const { data: masteryRows } = await db
          .from("topic_mastery")
          .select("topic, mastery_score, evidence_count")
          .eq("user_id", job.user_id)
          .eq("exam_id", job.exam_id)
          .gt("evidence_count", 0);

        if (masteryRows && masteryRows.length > 0) {
          const masteryByTopic: Record<string, number> = {};
          for (const row of masteryRows) {
            masteryByTopic[String(row.topic)] = Number(row.mastery_score) || 0;
          }
          candidates = [...candidates]
            .map((row, idx) => ({
              row,
              pri: adaptiveSoftPriority(
                row.topic as string | null,
                masteryByTopic,
                idx / Math.max(1, candidates.length - 1),
              ),
            }))
            .sort((a, b) => b.pri - a.pri)
            .map((x) => x.row);

          blueprint.label =
            "Adaptive practice set — soft-biased toward your weaker assessed topics. Not an official paper.";
        }
      } catch (masteryRankErr) {
        console.warn("[govPaperAssembly] mastery soft-rank skipped:", masteryRankErr);
      }
    }

    st = await stage(db, job.id, workerId, "validating_questions");
    if (st === "cancelled") {
      return { ok: false, status: "cancelled", errorCode: "CANCELLED", error: "Cancelled" };
    }
    if (st === "lost_lease") {
      return { ok: false, status: "failed", errorCode: "LEASE_LOST", error: "Lost job lease", httpStatus: 409 };
    }

    const selected: GapFillRow[] = [];
    const seenFp = new Set<string>();
    const rejectedQuality: Array<{ id: string; reason: string; score: number }> = [];
    const reviewQueue: unknown[] = [];
    const aiQuestionIds = new Set<string>();

    for (const row of candidates) {
      if (selected.length >= blueprint.total_questions) break;
      const text = String(row.question_text ?? "");
      const options = normalizeMcqOptions(row.options);
      const correctIndex = resolveCorrectIndex(row.correct_answer, options.length);
      if (correctIndex == null) {
        rejectedQuality.push({
          id: String(row.id),
          reason: "ANSWER_VERIFICATION_FAILED",
          score: 0,
        });
        continue;
      }

      const fp = questionFingerprint(text, options);
      if (seenFp.has(fp)) continue;

      const peerTexts = selected.map((p) => String(p.question_text ?? ""));
      if (conflictsWithSelected(text, peerTexts)) continue;

      const quality = scoreQuestionQuality({
        question_text: text,
        options,
        correct_index: correctIndex,
        peers: peerTexts,
        sourceConfidence: 0.8,
      });
      if (quality.hardFail || quality.score < MIN_BANK_QUESTION_QUALITY) {
        rejectedQuality.push({
          id: String(row.id),
          reason: quality.hardFailCodes[0] ?? "LOW_QUALITY",
          score: quality.score,
        });
        continue;
      }

      const agent = runBankMultiAgentValidation({
        question_text: text,
        options,
        correct_index: correctIndex,
        peers: peerTexts,
        sourceConfidence: 0.8,
        language: job.language,
      });
      if (!agent.publishable) {
        if (agent.disagreements.length) {
          reviewQueue.push({
            questionId: row.id,
            disagreements: agent.disagreements,
            qualityScore: agent.quality.score,
          });
        }
        rejectedQuality.push({
          id: String(row.id),
          reason: agent.disagreements[0]?.topic ?? "AGENT_REJECT",
          score: agent.quality.score,
        });
        continue;
      }

      seenFp.add(fp);
      selected.push(row);
    }

    st = await stage(db, job.id, workerId, "checking_similarity");
    if (st === "cancelled") {
      return { ok: false, status: "cancelled", errorCode: "CANCELLED", error: "Cancelled" };
    }
    if (st === "lost_lease") {
      return { ok: false, status: "failed", errorCode: "LEASE_LOST", error: "Lost job lease", httpStatus: 409 };
    }

    const requestedQuestionCount = blueprint.total_questions;

    const selectedStems = selected.map((q) => String(q.question_text ?? ""));
    const paperSim = validatePaperSimilarity(selectedStems);
    if (!paperSim.ok) {
      const drop = new Set<number>();
      for (const pair of paperSim.pairs) {
        drop.add(pair.j);
      }
      const filtered = selected.filter((_, idx) => !drop.has(idx));
      selected.length = 0;
      selected.push(...filtered);
    }

    const residualPairs = findNearDuplicatesInSet(
      selected.map((q) => String(q.question_text ?? "")),
    );
    if (residualPairs.length) {
      const drop = new Set(residualPairs.map((p) => p.j));
      const filtered = selected.filter((_, idx) => !drop.has(idx));
      selected.length = 0;
      selected.push(...filtered);
    }

    // Custom / adaptive practice: after the quality bar, take remaining unique
    // public bank items (fingerprint + valid answer only). Re-running paper-wide
    // near-dup collapse here is what shrunk IBPS custom sets from 50 → ~18.
    const allowRelaxedBank = mode === "custom_mock" || mode === "adaptive";
    if (allowRelaxedBank && selected.length < blueprint.total_questions) {
      const selectedIds = new Set(selected.map((r) => String(r.id)));
      for (const row of candidates) {
        if (selected.length >= blueprint.total_questions) break;
        if (selectedIds.has(String(row.id))) continue;
        const text = String(row.question_text ?? "");
        const options = normalizeMcqOptions(row.options);
        const correctIndex = resolveCorrectIndex(row.correct_answer, options.length);
        if (correctIndex == null) continue;
        const fp = questionFingerprint(text, options);
        if (seenFp.has(fp)) continue;
        seenFp.add(fp);
        selectedIds.add(String(row.id));
        selected.push(row);
      }
    }

    // Enforce server-side capability check for AI fill — direct edge invocations cannot bypass
    const { data: userProfile } = await db
      .from("profiles")
      .select("plan_id")
      .eq("id", job.user_id)
      .maybeSingle();

    const requestJson = (jobInput.request_json ?? {}) as Record<string, unknown>;
    const skipAiFill = requestJson.skipAiFill === true || requestJson.allowAiFill === false;
    const userCanAiFill = hasCapability(userProfile?.plan_id, "gov_exam_ai_fill");
    const allowAiFill = mode !== "official_previous" && userCanAiFill && !skipAiFill;
    let aiFilledCount = 0;
    let aiFillError: string | undefined;

    if (allowAiFill && selected.length < blueprint.total_questions) {
      st = await stage(db, job.id, workerId, "generating_questions");
      if (st === "cancelled") {
        return { ok: false, status: "cancelled", errorCode: "CANCELLED", error: "Cancelled" };
      }
      if (st === "lost_lease") {
        return { ok: false, status: "failed", errorCode: "LEASE_LOST", error: "Lost job lease", httpStatus: 409 };
      }

      // Drive generation from the approved blueprint and syllabus rather than from the
      // bank rows we happened to select: an exam with an empty bank still needs a
      // correctly scoped prompt.
      const subjects = [
        ...new Set([
          ...blueprint.sections.map((s) => String(s.name ?? "").trim()),
          ...selected.map((r) => String(r.subject ?? "").trim()),
        ].filter(Boolean)),
      ].slice(0, 8);

      const syllabusTopics = await loadSyllabusTopics(
        db,
        blueprint.syllabus_version_id,
      );
      const topics = [
        ...new Set([
          ...syllabusTopics,
          ...selected.map((r) => String(r.topic ?? "").trim()),
        ].filter(Boolean)),
      ].slice(0, 24);

      const fill = await fillUntilCount({
        db,
        targetCount: blueprint.total_questions,
        existing: selected,
        examType: insertExamType,
        subjects: subjects.length ? subjects : [String(exam.name ?? "General")],
        topics,
        marksPositive: blueprint.marks_per_question,
        marksNegative: blueprint.negative_mark,
        userId: job.user_id,
        onBatch: async () => {
          await heartbeatJobLease(db, job.id, workerId, 180_000);
        },
      });
      aiFillError = fill.error;
      for (const row of fill.added) {
        if (selected.length >= blueprint.total_questions) break;
        aiQuestionIds.add(row.id);
        selected.push(row);
      }
      aiFilledCount = fill.added.length;
    }

    const requireExact = mode === "official_previous" || mode === "generated_mock";

    if (selected.length < blueprint.total_questions) {
      if (requireExact) {
        const isCapBlocked = mode === "generated_mock" && !userCanAiFill && !skipAiFill;
        const errorCode = "QUESTION_INVENTORY_INSUFFICIENT";
        const errorMsg = isCapBlocked
          ? `AI question generation requires a Pro plan. Found ${selected.length}/${blueprint.total_questions} approved bank items.`
          : `Only ${selected.length} approved questions are available for this configuration.`;

        await failJob(
          db,
          job,
          workerId,
          errorCode,
          errorMsg,
          false,
        );
        return {
          ok: false,
          status: "failed",
          errorCode,
          error: errorMsg,
          available: selected.length,
          required: blueprint.total_questions,
          httpStatus: 422,
        };
      }
      if (selected.length < 5) {
        const quotaBlocked = /429|RESOURCE_EXHAUSTED|quota|rate.?limit/i.test(aiFillError ?? "");
        const fillDetail = quotaBlocked
          ? "AI question generation is rate-limited. Wait a minute and try again."
          : aiFillError
            ? aiFillError.replace(/\s+/g, " ").slice(0, 180)
            : "";
        await failJob(
          db,
          job,
          workerId,
          "INSUFFICIENT_APPROVED_QUESTIONS",
          fillDetail
            ? `Only ${selected.length} questions after bank + AI fill (${fillDetail})`
            : `Only ${selected.length} questions after bank + AI fill.`,
          quotaBlocked,
        );
        return {
          ok: false,
          status: "failed",
          errorCode: "INSUFFICIENT_APPROVED_QUESTIONS",
          error: fillDetail
            ? `Not enough questions (${selected.length}). ${fillDetail}`
            : "Not enough questions for a practice set.",
          available: selected.length,
          required: blueprint.total_questions,
          httpStatus: 422,
        };
      }
      blueprint.total_questions = selected.length;
      blueprint.total_marks = selected.length * blueprint.marks_per_question;
      blueprint.paper_class = aiFilledCount > 0 ? "ai_generated" : "custom_practice";
      blueprint.label =
        aiFilledCount > 0
          ? `AI-assisted practice set (${selected.length} of ${requestedQuestionCount} requested unique questions). Not an official or leaked examination paper.`
          : `Custom Practice Set — ${selected.length} of ${requestedQuestionCount} requested questions from available bank items. Not a full exam simulation.`;
      blueprint.slots = blueprint.slots.slice(0, selected.length);
    } else if (aiFilledCount > 0 && blueprint.paper_class !== "official_previous") {
      blueprint.paper_class = "ai_generated";
      blueprint.label =
        "AI-generated practice paper based on the selected syllabus, pattern, and historical topic distribution. This is not an official or leaked examination paper.";
    }

    // Hard constraint validation on assembled question set before freezing
    const assembledHard = validateAssembledPaperHardConstraints({
      blueprint,
      questions: selected.slice(0, blueprint.total_questions).map((r) => ({
        id: String(r.id),
        question_text: String(r.question_text ?? ""),
        options: r.options,
        correct_answer: r.correct_answer,
        subject: r.subject,
        topic: r.topic,
      })),
      aiQuestionIds,
    });

    if (!assembledHard.ok) {
      await failJob(
        db,
        job,
        workerId,
        "HARD_CONSTRAINT_VIOLATION",
        `Hard constraint violation: ${assembledHard.errors.join("; ")}`,
        false,
        { blueprint_json: blueprint },
      );
      return {
        ok: false,
        status: "failed",
        errorCode: "HARD_CONSTRAINT_VIOLATION",
        error: `Hard constraint violation: ${assembledHard.errors.join("; ")}`,
        httpStatus: 422,
      };
    }

    st = await stage(db, job.id, workerId, "assembling", { blueprint_json: blueprint });
    if (st === "cancelled") {
      return { ok: false, status: "cancelled", errorCode: "CANCELLED", error: "Cancelled" };
    }
    if (st === "lost_lease") {
      return { ok: false, status: "failed", errorCode: "LEASE_LOST", error: "Lost job lease", httpStatus: 409 };
    }

    const questionIds = selected.slice(0, blueprint.total_questions).map((q) => q.id);

    const paperQuality = scorePaperQuality(
      selected.slice(0, blueprint.total_questions).map((row) => {
        const options = normalizeMcqOptions(row.options);
        return {
          question_text: String(row.question_text ?? ""),
          options,
          correct_index: resolveCorrectIndex(row.correct_answer, options.length) ?? 0,
          peers: [],
          sourceConfidence: aiQuestionIds.has(row.id) ? 0.55 : 0.8,
        };
      }),
    );

    const { data: mockTest, error: mtErr } = await db
      .from("mock_tests")
      .insert({
        user_id: job.user_id,
        test_name:
          `${exam.name} · ${blueprint.paper_class === "ai_generated" ? "Pattern mock" : "Practice set"}`,
        question_ids: questionIds,
        time_limit_minutes: blueprint.duration_minutes,
        config: {
          exam_type: exam.code,
          gov_exam_id: job.exam_id,
          gov_stage_id: job.stage_id,
          pattern_version: blueprint.pattern_version,
          syllabus_version: blueprint.syllabus_version,
          paper_class: blueprint.paper_class,
          marks_positive: blueprint.marks_per_question,
          marks_negative: blueprint.negative_mark,
          duration_minutes: blueprint.duration_minutes,
          language: blueprint.language,
          source_years: blueprint.source_years,
          disclaimer: blueprint.label,
          generation_job_id: job.id,
          shuffle_questions: false,
          shuffle_options: false,
          quality_score: paperQuality.score,
          requested_question_count: requestedQuestionCount,
        },
        status: "DRAFT",
      })
      .select("id")
      .single();

    if (mtErr || !mockTest) {
      throw new Error(mtErr?.message ?? "mock_tests insert failed");
    }

    const { data: paper, error: paperErr } = await db
      .from("gov_generated_papers")
      .insert({
        exam_id: job.exam_id,
        stage_id: job.stage_id,
        pattern_version_id: pattern.id,
        syllabus_version_id: syllabus?.id ?? null,
        job_id: job.id,
        created_by: job.user_id,
        title: `${exam.name} practice paper`,
        paper_class: blueprint.paper_class,
        language: blueprint.language,
        question_count: questionIds.length,
        total_marks: blueprint.total_marks,
        duration_minutes: blueprint.duration_minutes,
        negative_mark: blueprint.negative_mark,
        blueprint_json: blueprint,
        provenance_json: {
          assembly: aiFilledCount > 0 ? "bank_plus_ai_fill_v1" : "bank_select_v1",
          seed: randomSeed,
          source_years: sourceYears,
          question_ids: questionIds,
          quality_score: paperQuality.score,
          quality_hard_fail_count: paperQuality.hardFailCount,
          rejected_quality_sample: rejectedQuality.slice(0, 20),
          review_queue: reviewQueue.slice(0, 50),
          llm_generator: aiFilledCount > 0,
          ai_filled_count: aiFilledCount,
          exam_type_keys: examTypeKeys,
          missing_coverage: selected.length < requestedQuestionCount ? {
            requested: requestedQuestionCount,
            provided: selected.length,
            deficit: requestedQuestionCount - selected.length,
          } : undefined,
          note:
            aiFilledCount > 0
              ? "Assembled from the approved public bank, then unique AI-generated MCQs filled remaining slots. Not an official paper."
              : "Assembled from approved public question bank; not an official paper.",
        },
        quality_score: paperQuality.score,
        review_state: paperQuality.hardFailCount > 0 || reviewQueue.length > 0
          ? "needs_review"
          : "machine_validated",
        disclaimer: blueprint.label,
        mock_test_id: mockTest.id,
      })
      .select("id")
      .single();

    if (paperErr || !paper) {
      throw new Error(paperErr?.message ?? "gov_generated_papers insert failed");
    }

    const linkRows = questionIds.map((qid, idx) => ({
      paper_id: paper.id,
      question_id: qid,
      section_code: blueprint.slots[idx]?.section_code ?? null,
      sort_order: idx,
      source_class: aiQuestionIds.has(qid) ? ("generated" as const) : ("bank" as const),
    }));

    if (linkRows.length) {
      await db.from("gov_generated_paper_questions").insert(linkRows);
    }

    await setJobIfActive(
      db,
      job.id,
      {
        status: "completed",
        progress_stage: "completed",
        mock_test_id: mockTest.id,
        generated_paper_id: paper.id,
        completed_at: new Date().toISOString(),
        blueprint_json: blueprint,
        worker_id: null,
        lease_expires_at: null,
        retryable: false,
      },
      { workerId },
    );

    return {
      ok: true,
      status: "completed",
      mockTestId: mockTest.id as string,
      paperId: paper.id as string,
      questionCount: questionIds.length,
      paperClass: blueprint.paper_class,
      disclaimer: blueprint.label,
      patternVersion: blueprint.pattern_version,
      syllabusVersion: blueprint.syllabus_version,
    };
  } catch (procErr) {
    console.error("[govPaperAssembly] process:", procErr);
    // Transient failures stay retryable so a worker can reclaim after lease expiry.
    await failJob(
      db,
      job,
      workerId,
      "PAPER_GENERATION_FAILED",
      "Generation failed",
      true,
    );
    return {
      ok: false,
      status: "failed",
      errorCode: "PAPER_GENERATION_FAILED",
      error: "Paper generation failed",
      httpStatus: 500,
    };
  }
}

/** Claim (if needed) + assemble a specific job id. */
export async function processPaperGenerationJobById(
  jobId: string,
  opts: { workerId?: string; userId?: string } = {},
): Promise<AssemblyResult & { jobId: string; workerId?: string; attemptCount?: number }> {
  const db = createServiceClient();
  const claimed = await claimPaperGenerationJob(db, {
    jobId,
    workerId: opts.workerId,
    userId: opts.userId,
  });
  if (!claimed.ok) {
    if (claimed.reason === "max_attempts") {
      return {
        jobId,
        ok: false,
        status: "failed",
        errorCode: "MAX_ATTEMPTS",
        error: "Exceeded max processing attempts",
        httpStatus: 422,
      };
    }
    // Idempotent: already completed
    const { data: existing } = await db
      .from("gov_paper_generation_jobs")
      .select("id, status, mock_test_id, generated_paper_id, error_code, error_message")
      .eq("id", jobId)
      .maybeSingle();
    if (existing?.status === "completed" && existing.mock_test_id && existing.generated_paper_id) {
      return {
        jobId,
        ok: true,
        status: "completed",
        mockTestId: existing.mock_test_id,
        paperId: existing.generated_paper_id,
        questionCount: 0,
        paperClass: "custom_practice",
        disclaimer: "",
        patternVersion: null,
        syllabusVersion: null,
      };
    }
    if (existing?.status === "cancelled") {
      return {
        jobId,
        ok: false,
        status: "cancelled",
        errorCode: "CANCELLED",
        error: "Cancelled",
      };
    }
    return {
      jobId,
      ok: false,
      status: "failed",
      errorCode: "NOT_CLAIMABLE",
      error: claimed.message ?? "Job not claimable",
      httpStatus: 409,
    };
  }

  const result = await assembleClaimedPaperJob(db, claimed.job, claimed.workerId);
  return {
    jobId,
    workerId: claimed.workerId,
    attemptCount: claimed.attemptCount,
    ...result,
  };
}

/** Detect EdgeRuntime.waitUntil without hard dependency. */
export function scheduleWithWaitUntil(task: Promise<unknown>): boolean {
  try {
    const er = (globalThis as unknown as {
      EdgeRuntime?: { waitUntil?: (p: Promise<unknown>) => void };
    }).EdgeRuntime;
    if (er && typeof er.waitUntil === "function") {
      er.waitUntil(
        task.catch((err) => {
          console.error("[govPaperAssembly] background task:", err);
        }),
      );
      return true;
    }
  } catch {
    // ignore
  }
  return false;
}

/**
 * Deno mirror of src/lib/gov-exam/masteryEngine.ts — keep formulas in sync.
 */

export type MasteryState =
  | "not_assessed"
  | "foundation_needed"
  | "developing"
  | "practicing"
  | "strong"
  | "exam_ready";

export type DifficultyBand = "easy" | "medium" | "hard" | "unknown";

export type MasteryConfig = {
  learningRate: number;
  clampMin: number;
  clampMax: number;
  minEvidenceForState: Record<Exclude<MasteryState, "not_assessed">, number>;
  scoreThresholds: Record<Exclude<MasteryState, "not_assessed">, number>;
  difficultyFactors: Record<DifficultyBand, number>;
};

export const DEFAULT_MASTERY_CONFIG: MasteryConfig = {
  learningRate: 0.18,
  clampMin: 0,
  clampMax: 1,
  minEvidenceForState: {
    foundation_needed: 1,
    developing: 3,
    practicing: 6,
    strong: 10,
    exam_ready: 15,
  },
  scoreThresholds: {
    foundation_needed: 0,
    developing: 0.35,
    practicing: 0.55,
    strong: 0.75,
    exam_ready: 0.88,
  },
  difficultyFactors: {
    easy: 0.75,
    medium: 1.0,
    hard: 1.25,
    unknown: 1.0,
  },
};

export const MASTERY_ALGORITHM_VERSION = "mastery_v1";

export type TopicMasteryRow = {
  topic: string;
  mastery_score: number;
  state: MasteryState;
  evidence_count: number;
};

export type AttemptSignal = {
  correct: boolean;
  attempted: boolean;
  difficulty?: DifficultyBand | string | null;
  daysAgo?: number;
  quality?: number;
};

function clamp(n: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, n));
}

export function normalizeDifficulty(raw: unknown): DifficultyBand {
  const v = String(raw ?? "").trim().toLowerCase();
  if (v === "easy" || v === "e") return "easy";
  if (v === "hard" || v === "h" || v === "difficult") return "hard";
  if (v === "medium" || v === "med" || v === "m" || v === "moderate") return "medium";
  return "unknown";
}

export function recencyFactor(daysAgo = 0): number {
  const d = Math.max(0, daysAgo);
  if (d <= 0) return 1;
  if (d <= 7) return 0.95;
  if (d <= 30) return 0.85;
  if (d <= 90) return 0.7;
  return 0.55;
}

export function performanceSignal(
  attempt: Pick<AttemptSignal, "correct" | "attempted">,
): number {
  if (!attempt.attempted) return 0;
  return attempt.correct ? 1 : -1;
}

export function resolveMasteryState(
  masteryScore: number,
  evidenceCount: number,
  config: MasteryConfig = DEFAULT_MASTERY_CONFIG,
): MasteryState {
  if (evidenceCount < config.minEvidenceForState.foundation_needed) {
    return "not_assessed";
  }
  const score = clamp(masteryScore, config.clampMin, config.clampMax);
  const order: Exclude<MasteryState, "not_assessed">[] = [
    "exam_ready",
    "strong",
    "practicing",
    "developing",
    "foundation_needed",
  ];
  for (const state of order) {
    if (
      evidenceCount >= config.minEvidenceForState[state] &&
      score >= config.scoreThresholds[state]
    ) {
      return state;
    }
  }
  return "foundation_needed";
}

export function updateMasteryScore(
  prior: number,
  signal: AttemptSignal,
  config: MasteryConfig = DEFAULT_MASTERY_CONFIG,
): number {
  const quality = clamp(signal.quality ?? 1, 0.2, 1);
  const difficulty = config.difficultyFactors[normalizeDifficulty(signal.difficulty)];
  const perf = performanceSignal(signal);
  const recency = recencyFactor(signal.daysAgo ?? 0);
  const delta = config.learningRate * quality * difficulty * perf * recency;
  return clamp(prior + delta, config.clampMin, config.clampMax);
}

export function applyAttemptToMastery(
  prior: TopicMasteryRow | null | undefined,
  signal: AttemptSignal,
  config: MasteryConfig = DEFAULT_MASTERY_CONFIG,
): TopicMasteryRow {
  const topic = prior?.topic ?? "";
  const evidenceBump = signal.attempted ? 1 : 0;
  const evidence_count = (prior?.evidence_count ?? 0) + evidenceBump;
  const priorScore =
    prior && prior.evidence_count > 0 ? prior.mastery_score : 0.45;
  const mastery_score = signal.attempted
    ? updateMasteryScore(priorScore, signal, config)
    : clamp(prior?.mastery_score ?? 0, config.clampMin, config.clampMax);
  const state = resolveMasteryState(mastery_score, evidence_count, config);
  return { topic, mastery_score, state, evidence_count };
}

export function applyBatchToMastery(
  prior: TopicMasteryRow | null | undefined,
  attempts: AttemptSignal[],
  config: MasteryConfig = DEFAULT_MASTERY_CONFIG,
): TopicMasteryRow {
  let current: TopicMasteryRow = {
    topic: prior?.topic ?? "",
    mastery_score: prior?.mastery_score ?? 0,
    state: prior?.state ?? "not_assessed",
    evidence_count: prior?.evidence_count ?? 0,
  };
  for (const attempt of attempts) {
    current = applyAttemptToMastery(current, attempt, config);
  }
  return current;
}

export function listWeakTopics(
  rows: TopicMasteryRow[],
  limit = 5,
): Array<{
  topic: string;
  mastery_score: number;
  state: MasteryState;
  evidence_count: number;
}> {
  return [...rows]
    .filter(
      (r) =>
        r.evidence_count > 0 &&
        (r.state === "foundation_needed" ||
          r.state === "developing" ||
          r.state === "practicing" ||
          r.mastery_score < 0.65),
    )
    .sort((a, b) => a.mastery_score - b.mastery_score)
    .slice(0, limit)
    .map((r) => ({
      topic: r.topic,
      mastery_score: r.mastery_score,
      state: r.state,
      evidence_count: r.evidence_count,
    }));
}

export type ReadinessBreakdown = {
  topic_count: number;
  assessed_count: number;
  mean_mastery: number | null;
  weak_count: number;
  strong_count: number;
  exam_ready_count: number;
  coverage: number;
  weak_topics: string[];
  recommended_action: string;
  algorithm_version: string;
};

export function computeExamReadiness(
  rows: TopicMasteryRow[],
  syllabusTopicCount?: number | null,
): { score: number; breakdown: ReadinessBreakdown } {
  const assessed = rows.filter((r) => r.evidence_count > 0);
  const topic_count = rows.length;
  const assessed_count = assessed.length;

  if (assessed_count === 0) {
    return {
      score: 0,
      breakdown: {
        topic_count,
        assessed_count: 0,
        mean_mastery: null,
        weak_count: 0,
        strong_count: 0,
        exam_ready_count: 0,
        coverage: 0,
        weak_topics: [],
        recommended_action:
          "Complete a practice paper to start measuring topic mastery. No readiness estimate yet.",
        algorithm_version: MASTERY_ALGORITHM_VERSION,
      },
    };
  }

  const mean_mastery =
    assessed.reduce((s, r) => s + r.mastery_score, 0) / assessed_count;
  const weak = listWeakTopics(assessed, 5);
  const strong_count = assessed.filter(
    (r) => r.state === "strong" || r.state === "exam_ready",
  ).length;
  const exam_ready_count = assessed.filter((r) => r.state === "exam_ready").length;
  const denom =
    syllabusTopicCount && syllabusTopicCount > 0
      ? syllabusTopicCount
      : Math.max(topic_count, assessed_count);
  const coverage = clamp(assessed_count / denom, 0, 1);
  const score = Math.round(100 * mean_mastery * (0.55 + 0.45 * coverage));

  let recommended_action: string;
  if (coverage < 0.35) {
    recommended_action =
      "Broaden coverage with a mixed practice set — too few topics assessed for a stable readiness signal.";
  } else if (weak.length > 0) {
    recommended_action = `Focus next on ${weak
      .slice(0, 2)
      .map((w) => w.topic)
      .join(" and ")} — lowest mastery among assessed topics.`;
  } else if (mean_mastery >= 0.8) {
    recommended_action =
      "Run a full-pattern simulation to stress-test timing under exam conditions.";
  } else {
    recommended_action =
      "Keep practicing medium-difficulty mixed sets to push developing topics toward strong.";
  }

  return {
    score,
    breakdown: {
      topic_count,
      assessed_count,
      mean_mastery: Math.round(mean_mastery * 1000) / 1000,
      weak_count: weak.length,
      strong_count,
      exam_ready_count,
      coverage: Math.round(coverage * 1000) / 1000,
      weak_topics: weak.map((w) => w.topic),
      recommended_action,
      algorithm_version: MASTERY_ALGORITHM_VERSION,
    },
  };
}

export function buildPreparationPlan(
  rows: TopicMasteryRow[],
  readiness: { score: number; breakdown: ReadinessBreakdown },
): Record<string, unknown> {
  const weak = listWeakTopics(rows, 8);
  return {
    version: MASTERY_ALGORITHM_VERSION,
    updated_hint: "Derived from topic_mastery after practice attempts.",
    readiness_score: readiness.score,
    focus_topics: weak.map((w) => ({
      topic: w.topic,
      mastery_score: w.mastery_score,
      state: w.state,
    })),
    next_action: readiness.breakdown.recommended_action,
    empty: rows.every((r) => r.evidence_count === 0),
  };
}

export function adaptiveSoftPriority(
  topic: string | null | undefined,
  masteryByTopic: Record<string, number>,
  seededRank01: number,
  weaknessWeight = 0.65,
): number {
  const key = String(topic ?? "").trim();
  const mastery =
    key && key in masteryByTopic ? clamp(masteryByTopic[key], 0, 1) : 0.5;
  const weakness = 1 - mastery;
  const noise = clamp(seededRank01, 0, 1);
  return weaknessWeight * weakness + (1 - weaknessWeight) * noise;
}

/**
 * Bank-shortfall MCQ generation for gov mocks.
 * Inserts original Gemini MCQs (not claimed as official papers) until the
 * requested count is reached, with fingerprint + quality dedup.
 */

import { createServiceClient } from "./supabase.ts";
import { generateWithFallback } from "./aiProvider.ts";
import { parseJSON } from "./gemini.ts";
import { buildGapFillPrompt, type WeakTopicStat } from "./examAIPrompts.ts";
import {
  conflictsWithSelected,
  normalizeMcqOptions,
  optionsForStorage,
  questionFingerprint,
  resolveCorrectIndex,
  validateSingleCorrectMcq,
} from "./govMcqValidator.ts";
import { MIN_BANK_QUESTION_QUALITY, scoreQuestionQuality } from "./govQualityScore.ts";

export const GAP_FILL_BATCH = 10;
export const GAP_FILL_MAX_BATCHES = 16;

export type GapFillRow = {
  id: string;
  question_text: string;
  options: unknown;
  correct_answer: string;
  subject: string | null;
  topic: string | null;
  difficulty: string | null;
  source: string | null;
  source_year: number | null;
  is_public: boolean | null;
  is_verified: boolean | null;
};

type ServiceDb = ReturnType<typeof createServiceClient>;

function getSystemUserId(): string | null {
  const id = Deno.env.get("SYSTEM_USER_ID");
  if (!id || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id)) {
    return null;
  }
  return id;
}

function letterForIndex(idx: number): string {
  return ["A", "B", "C", "D"][idx] ?? "A";
}

export type FillUntilOpts = {
  db: ServiceDb;
  targetCount: number;
  existing: GapFillRow[];
  examType: string;
  subjects: string[];
  topics: string[];
  difficultyMix?: { EASY: number; MEDIUM: number; HARD: number };
  weakTopics?: WeakTopicStat[];
  strongTopics?: string[];
  marksPositive?: number;
  marksNegative?: number;
  userId?: string;
  onBatch?: () => Promise<void>;
};

/**
 * Generate and insert unique MCQs until `existing.length + added >= targetCount`.
 * Returns only the newly inserted rows.
 */
export async function fillUntilCount(
  opts: FillUntilOpts,
): Promise<{ added: GapFillRow[]; error?: string }> {
  if (
    !Deno.env.get("GEMINI_API_KEY")?.trim() &&
    !Deno.env.get("OPENAI_API_KEY")?.trim() &&
    !Deno.env.get("ANTHROPIC_API_KEY")?.trim()
  ) {
    return { added: [], error: "No AI provider key configured on Supabase" };
  }

  const added: GapFillRow[] = [];
  const selectedTexts = [
    ...opts.existing.map((r) => String(r.question_text ?? "")),
  ];
  const seenFp = new Set<string>(
    [...opts.existing, ...added].map((r) =>
      questionFingerprint(String(r.question_text ?? ""), normalizeMcqOptions(r.options)),
    ),
  );

  let lastError: string | undefined;
  let emptyBatches = 0;

  for (let batch = 0; batch < GAP_FILL_MAX_BATCHES; batch++) {
    const have = opts.existing.length + added.length;
    if (have >= opts.targetCount) break;

    if (opts.onBatch) {
      await opts.onBatch();
    }

    const need = Math.min(GAP_FILL_BATCH, opts.targetCount - have);
    const result = await generateAndInsertBatch({
      db: opts.db,
      gapCount: need,
      examType: opts.examType,
      subjects: opts.subjects,
      topics: opts.topics,
      difficultyMix: opts.difficultyMix ?? { EASY: 20, MEDIUM: 60, HARD: 20 },
      weakTopics: opts.weakTopics ?? [],
      strongTopics: opts.strongTopics ?? [],
      avoidStems: selectedTexts.slice(-14),
      batchIndex: batch,
      seenFp,
      selectedTexts,
      marksPositive: opts.marksPositive ?? 1,
      marksNegative: opts.marksNegative ?? 0,
      userId: opts.userId,
    });

    if (result.error) lastError = result.error;
    const quotaHit = /429|RESOURCE_EXHAUSTED|quota|rate.?limit/i.test(result.error ?? "");
    if (result.rows.length === 0) {
      // generateWithFallback already exhausted Gemini + OpenAI/Anthropic.
      if (quotaHit) break;
      emptyBatches += 1;
      if (emptyBatches >= 3) break;
      continue;
    }
    emptyBatches = 0;
    for (const row of result.rows) {
      added.push(row);
      selectedTexts.push(String(row.question_text ?? ""));
    }
  }

  if (opts.existing.length + added.length < opts.targetCount && lastError) {
    return { added, error: lastError };
  }
  return { added };
}

async function generateAndInsertBatch(args: {
  db: ServiceDb;
  gapCount: number;
  examType: string;
  subjects: string[];
  topics: string[];
  difficultyMix: { EASY: number; MEDIUM: number; HARD: number };
  weakTopics: WeakTopicStat[];
  strongTopics: string[];
  avoidStems: string[];
  batchIndex: number;
  seenFp: Set<string>;
  selectedTexts: string[];
  marksPositive: number;
  marksNegative: number;
  userId?: string;
}): Promise<{ rows: GapFillRow[]; error?: string }> {
  const subj = args.subjects[0] ?? "General";
  const examStr = args.examType || "General Competitive Exam";
  const prompt = buildGapFillPrompt({
    examType: examStr,
    subjects: args.subjects.length ? args.subjects : [subj],
    topics: args.topics,
    weakTopics: args.weakTopics,
    strongTopics: args.strongTopics,
    difficultyMix: args.difficultyMix,
    gapCount: args.gapCount,
    avoidStems: args.avoidStems,
    batchIndex: args.batchIndex,
  });

  let raw: string;
  try {
    const generated = await generateWithFallback({
      prompt,
      temperature: 0.85,
      maxTokens: 8192,
      jsonMode: true,
      userId: args.userId ?? getSystemUserId() ?? "gap-fill",
      action: "gov_ai_gap_fill",
    });
    raw = generated.text;
  } catch (err) {
    const message = err instanceof Error ? err.message : "AI gap-fill failed";
    console.warn("[govAiGapFill] generate error:", message);
    return { rows: [], error: message };
  }

  const data = parseJSON(raw, { questions: [] as unknown[] });
  const qs = Array.isArray(data.questions) ? data.questions : [];
  const systemUserId = getSystemUserId();
  const inserts: Record<string, unknown>[] = [];

  for (const q of qs) {
    if (typeof q !== "object" || q === null) continue;
    const rec = q as Record<string, unknown>;
    const text = String(rec.question_text ?? "").trim().slice(0, 1000)
      .replace(/!\[[^\]]*]\([^)]*\)/g, "")
      .replace(/^\s*(reference\s+image|\[figure\])\s*$/gim, "")
      .trim();
    if (text.length < 10) continue;

    const optionTexts = normalizeMcqOptions(rec.options);
    if (optionTexts.length < 4) continue;

    const correctIndex = resolveCorrectIndex(rec.correct_answer, optionTexts.length);
    if (correctIndex == null) continue;

    const mcq = validateSingleCorrectMcq({
      question_text: text,
      options: optionTexts,
      correct_index: correctIndex,
    });
    if (!mcq.ok) continue;

    const fp = questionFingerprint(text, optionTexts);
    if (args.seenFp.has(fp)) continue;
    if (conflictsWithSelected(text, args.selectedTexts)) continue;

    const quality = scoreQuestionQuality({
      question_text: text,
      options: optionTexts,
      correct_index: correctIndex,
      peers: args.selectedTexts,
      sourceConfidence: 0.55,
    });
    if (quality.hardFail || quality.score < MIN_BANK_QUESTION_QUALITY) continue;

    const diffRaw = String(rec.difficulty ?? "").toUpperCase();
    const difficulty = ["EASY", "MEDIUM", "HARD"].includes(diffRaw) ? diffRaw : "MEDIUM";
    const topic =
      String(rec.topic ?? args.topics[0] ?? "General").slice(0, 100) || "General";
    const subject =
      String(rec.subject ?? subj).slice(0, 100) || subj;

    args.seenFp.add(fp);
    args.selectedTexts.push(text);
    inserts.push({
      question_text: text,
      question_type: "MCQ",
      options: optionsForStorage(optionTexts),
      correct_answer: letterForIndex(correctIndex),
      explanation: rec.explanation ? String(rec.explanation).slice(0, 1000) : "",
      subject,
      topic,
      difficulty,
      exam_type: args.examType || null,
      source: "AI_GENERATED",
      is_verified: false,
      is_public: false,
      uploaded_by: systemUserId,
      marks_positive: args.marksPositive,
      marks_negative: args.marksNegative,
      latex_present: /[=+\-*/^]/.test(text),
    });
  }

  if (inserts.length === 0) {
    return { rows: [], error: "Gemini returned no unique valid MCQs in this batch" };
  }

  const { data: inserted, error } = await args.db
    .from("questions")
    .insert(inserts)
    .select(
      "id, question_text, options, correct_answer, subject, topic, difficulty, source, source_year, is_public, is_verified",
    );

  if (error) {
    console.warn("[govAiGapFill] insert failed:", error.message);
    return { rows: [], error: `Database insert failed: ${error.message}` };
  }

  return { rows: (inserted ?? []) as GapFillRow[] };
}

/**
 * Independent quality score for bank assembly (mirrors src validators/qualityScore).
 * Does not use generator self-score.
 */

import {
  conflictsWithSelected,
  questionFingerprint,
  similarityBreakdown,
  validateSingleCorrectMcq,
} from "./govMcqValidator.ts";

export type QualityComponent = {
  id: string;
  weight: number;
  score: number;
  passed: boolean;
  detail?: string;
};

export type QualityScoreResult = {
  score: number;
  components: QualityComponent[];
  hardFail: boolean;
  hardFailCodes: string[];
};

export type BankMcqInput = {
  question_text: string;
  options: string[];
  correct_index: number;
  explanation?: string | null;
  peers?: string[];
  nearDupThreshold?: number;
  sourceConfidence?: number;
};

function clamp01(n: number): number {
  if (!Number.isFinite(n)) return 0;
  return Math.max(0, Math.min(1, n));
}

export const MIN_BANK_QUESTION_QUALITY = 40;

export function scoreQuestionQuality(input: BankMcqInput): QualityScoreResult {
  const components: QualityComponent[] = [];
  const hardFailCodes: string[] = [];

  const mcq = validateSingleCorrectMcq(input);
  components.push({
    id: "mcq_structure",
    weight: 0.3,
    score: mcq.ok ? 1 : 0,
    passed: mcq.ok,
    detail: mcq.ok ? undefined : mcq.message,
  });
  if (!mcq.ok) hardFailCodes.push(mcq.code);

  const peers = input.peers ?? [];
  const thresh = input.nearDupThreshold ?? 0.88;
  let simScore = 1;
  let simPassed = true;
  let simDetail: string | undefined;
  if (peers.length) {
    if (conflictsWithSelected(input.question_text, peers, thresh)) {
      simScore = 0;
      simPassed = false;
      simDetail = "Near-duplicate of another question in the paper.";
      hardFailCodes.push("NEAR_DUPLICATE");
    } else {
      let maxPeer = 0;
      for (const p of peers) {
        maxPeer = Math.max(maxPeer, similarityBreakdown(input.question_text, p).score);
      }
      simScore = clamp01(1 - Math.max(0, maxPeer - 0.5) * 0.5);
    }
  }
  components.push({
    id: "similarity",
    weight: 0.25,
    score: simScore,
    passed: simPassed,
    detail: simDetail,
  });

  const stemLen = (input.question_text ?? "").trim().length;
  const lengthScore =
    stemLen < 8 ? 0 : stemLen < 20 ? 0.5 : stemLen > 1200 ? 0.6 : 1;
  components.push({
    id: "stem_length",
    weight: 0.15,
    score: lengthScore,
    passed: stemLen >= 8,
  });
  if (stemLen < 8) hardFailCodes.push("QUESTION_VALIDATION_FAILED");

  const expl = Boolean(String(input.explanation ?? "").trim());
  components.push({
    id: "explanation_present",
    weight: 0.1,
    score: expl ? 1 : 0.4,
    passed: true,
  });

  const src = clamp01(input.sourceConfidence ?? 0.75);
  components.push({
    id: "source_confidence",
    weight: 0.1,
    score: src,
    passed: src >= 0.4,
  });

  const fp = questionFingerprint(input.question_text, input.options);
  components.push({
    id: "fingerprint",
    weight: 0.1,
    score: fp.length > 4 ? 1 : 0,
    passed: fp.length > 4,
  });

  const weightSum = components.reduce((a, c) => a + c.weight, 0) || 1;
  const weighted =
    components.reduce((a, c) => a + c.score * c.weight, 0) / weightSum;
  const hardFail = hardFailCodes.length > 0;
  const score = hardFail ? 0 : Math.round(weighted * 1000) / 10;

  return { score, components, hardFail, hardFailCodes: [...new Set(hardFailCodes)] };
}

export function scorePaperQuality(questions: BankMcqInput[]): {
  score: number;
  perQuestion: QualityScoreResult[];
  hardFailCount: number;
} {
  const perQuestion = questions.map((q) => scoreQuestionQuality(q));
  const hardFailCount = perQuestion.filter((r) => r.hardFail).length;
  const score =
    perQuestion.length === 0
      ? 0
      : Math.round(
        (perQuestion.reduce((a, r) => a + r.score, 0) / perQuestion.length) * 10,
      ) / 10;
  return { score, perQuestion, hardFailCount };
}

/**
 * Similarity + MCQ validation for create-exam-paper (mirrors src/lib/gov-exam).
 */

const LATEX_OR_GREEK: Array<[RegExp, string]> = [
  [/\\alpha|α/gi, " alpha "],
  [/\\beta|β/gi, " beta "],
  [/\\gamma|γ/gi, " gamma "],
  [/\\theta|θ/gi, " theta "],
  [/\\pi|π/gi, " pi "],
  [/\\omega|ω/gi, " omega "],
  [/\\sigma|σ/gi, " sigma "],
  [/\\lambda|λ/gi, " lambda "],
  [/\\mu|μ/gi, " mu "],
  [/\\delta|\\Delta|δ|Δ/gi, " delta "],
];

function expandMathTokens(text: string): string {
  let t = text;
  for (const [re, rep] of LATEX_OR_GREEK) t = t.replace(re, rep);
  return t.replace(/\\[a-zA-Z]+/g, " ");
}

export function normalizeQuestionText(text: string): string {
  return expandMathTokens(text)
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s]/gu, " ")
    .replace(/\s+/g, " ")
    .trim();
}

export function tokenize(text: string): string[] {
  const n = normalizeQuestionText(text);
  return n ? n.split(" ").filter(Boolean) : [];
}

export function questionFingerprint(text: string, options: string[] = []): string {
  const base = normalizeQuestionText(text);
  const opts = options.map(normalizeQuestionText).sort().join("|");
  return `${base}::${opts}`;
}

export function tokenJaccard(a: string, b: string): number {
  const ta = new Set(tokenize(a));
  const tb = new Set(tokenize(b));
  if (ta.size === 0 && tb.size === 0) return 1;
  if (ta.size === 0 || tb.size === 0) return 0;
  let inter = 0;
  for (const t of ta) if (tb.has(t)) inter += 1;
  const union = ta.size + tb.size - inter;
  return union > 0 ? inter / union : 0;
}

export function charNgrams(text: string, n = 3): Set<string> {
  const s = normalizeQuestionText(text).replace(/\s+/g, "");
  const out = new Set<string>();
  if (s.length < n) {
    if (s) out.add(s);
    return out;
  }
  for (let i = 0; i <= s.length - n; i++) out.add(s.slice(i, i + n));
  return out;
}

export function ngramJaccard(a: string, b: string, n = 3): number {
  const aa = charNgrams(a, n);
  const bb = charNgrams(b, n);
  if (aa.size === 0 && bb.size === 0) return 1;
  if (aa.size === 0 || bb.size === 0) return 0;
  let inter = 0;
  for (const g of aa) if (bb.has(g)) inter += 1;
  const union = aa.size + bb.size - inter;
  return union > 0 ? inter / union : 0;
}

export type SimilarityBreakdown = {
  exact: boolean;
  containment: number;
  tokenJaccard: number;
  ngramJaccard: number;
  score: number;
};

export function similarityBreakdown(a: string, b: string): SimilarityBreakdown {
  const na = normalizeQuestionText(a);
  const nb = normalizeQuestionText(b);
  if (!na || !nb) {
    return { exact: false, containment: 0, tokenJaccard: 0, ngramJaccard: 0, score: 0 };
  }
  const exact = na === nb;
  const shorter = na.length <= nb.length ? na : nb;
  const longer = na.length <= nb.length ? nb : na;
  const containment =
    longer.includes(shorter) && shorter.length > 0
      ? shorter.length / longer.length
      : 0;
  const tj = tokenJaccard(na, nb);
  const nj = ngramJaccard(na, nb, 3);
  const score = Math.max(exact ? 1 : 0, containment, tj, nj);
  return { exact, containment, tokenJaccard: tj, ngramJaccard: nj, score };
}

export function isNearDuplicate(a: string, b: string, threshold = 0.88): boolean {
  const d = similarityBreakdown(a, b);
  if (d.exact) return true;
  return d.score >= threshold;
}

export function conflictsWithSelected(
  candidate: string,
  selectedTexts: string[],
  threshold = 0.88,
): boolean {
  for (const prev of selectedTexts) {
    if (isNearDuplicate(candidate, prev, threshold)) return true;
  }
  return false;
}

export function findNearDuplicatesInSet(
  texts: string[],
  threshold = 0.88,
): Array<{ i: number; j: number; score: number }> {
  const pairs: Array<{ i: number; j: number; score: number }> = [];
  for (let i = 0; i < texts.length; i++) {
    for (let j = i + 1; j < texts.length; j++) {
      const d = similarityBreakdown(texts[i], texts[j]);
      if (d.exact || d.score >= threshold) {
        pairs.push({ i, j, score: d.score });
      }
    }
  }
  return pairs;
}

export function validateSingleCorrectMcq(q: {
  question_text: string;
  options: string[];
  correct_index: number;
}): { ok: true } | { ok: false; code: string; message: string } {
  const text = q.question_text?.trim() ?? "";
  if (text.length < 8) {
    return { ok: false, code: "QUESTION_VALIDATION_FAILED", message: "Question text too short." };
  }
  if (!Array.isArray(q.options) || q.options.length < 2) {
    return { ok: false, code: "QUESTION_VALIDATION_FAILED", message: "Need at least 2 options." };
  }
  if (q.options.some((o) => !String(o ?? "").trim())) {
    return { ok: false, code: "QUESTION_VALIDATION_FAILED", message: "Empty option." };
  }
  const normalized = q.options.map((o) => o.trim().toLowerCase());
  if (new Set(normalized).size !== normalized.length) {
    return { ok: false, code: "QUESTION_VALIDATION_FAILED", message: "Duplicate options." };
  }
  if (
    !Number.isInteger(q.correct_index) ||
    q.correct_index < 0 ||
    q.correct_index >= q.options.length
  ) {
    return {
      ok: false,
      code: "ANSWER_VERIFICATION_FAILED",
      message: "correct_index out of range.",
    };
  }
  return { ok: true };
}

const LETTERS = ["A", "B", "C", "D", "E", "F"] as const;

/** Extract display text from a bank option (string or `{label,text}` object). */
export function optionText(raw: unknown): string {
  if (typeof raw === "string") return raw.trim();
  if (raw && typeof raw === "object") {
    const rec = raw as Record<string, unknown>;
    const t = rec.text ?? rec.value;
    if (typeof t === "string" && t.trim()) return t.trim();
    if (typeof rec.label === "string" && rec.label.trim().length > 1) {
      return rec.label.trim();
    }
  }
  return "";
}

/**
 * Normalize questions.options JSON into 2–4 unique option strings.
 * Bank rows store `[{label:'A', text:'...'}]`; String(object) is "[object Object]"
 * and falsely fails quality as duplicate options.
 */
export function normalizeMcqOptions(raw: unknown, max = 4): string[] {
  if (!Array.isArray(raw)) return [];
  const texts = raw.map(optionText).filter(Boolean).slice(0, max);
  return texts;
}

export function optionsForStorage(
  texts: string[],
): Array<{ label: string; text: string }> {
  return texts.slice(0, 4).map((text, i) => ({
    label: LETTERS[i] ?? String(i + 1),
    text,
  }));
}

/** Resolve bank correct_answer letter or numeric string to 0-based index. */
export function resolveCorrectIndex(
  correctAnswer: unknown,
  optionCount: number,
): number | null {
  if (typeof correctAnswer === "number" && Number.isInteger(correctAnswer)) {
    return correctAnswer >= 0 && correctAnswer < optionCount ? correctAnswer : null;
  }
  const raw = String(correctAnswer ?? "").trim().toUpperCase();
  const letterIdx = LETTERS.indexOf(raw as (typeof LETTERS)[number]);
  if (letterIdx >= 0 && letterIdx < optionCount) return letterIdx;
  const asNum = Number(raw);
  if (Number.isInteger(asNum) && asNum >= 0 && asNum < optionCount) return asNum;
  // 1-based numeric
  if (Number.isInteger(asNum) && asNum >= 1 && asNum <= optionCount) return asNum - 1;
  return null;
}

