// supabase/functions/_shared/gemini.ts
//
// Shared Gemini API helper for names// Shared Gemini API helper for Supabase Edge Functions.
// - Enforce timeout
// - Sanitize prompts
// - Avoid logging secrets
// - Safely parse Gemini JSON-like responses
// - Normalize Gemini errors without leaking sensitive data

const GEMINI_API_VERSION = Deno.env.get("GEMINI_API_VERSION") ?? "v1beta";
const GEMINI_BASE = `https://generativelanguage.googleapis.com/${GEMINI_API_VERSION}`;
const DEFAULT_MODEL =
  Deno.env.get("GEMINI_MODEL_DEFAULT") ?? "gemini-2.5-flash";

const DEFAULT_TIMEOUT_MS = 50_000;
const MAX_PROMPT_LENGTH = 100_000;
const MAX_SYSTEM_PROMPT_LENGTH = 20_000;
const MAX_ERROR_TEXT_LENGTH = 1_000;

export interface GeminiPart {
  text: string;
}

export interface GeminiMessage {
  role: "user" | "model";
  parts: GeminiPart[];
}

export type GeminiRequestOptions = {
  model?: string;
  stream?: boolean;
  timeoutMs?: number;
};

type GeminiCandidatePart = {
  text?: string;
};

type GeminiCandidateContent = {
  parts?: GeminiCandidatePart[];
};

type GeminiCandidate = {
  content?: GeminiCandidateContent;
};

type GeminiResponse = {
  candidates?: GeminiCandidate[];
};

function getServerGeminiKey(): string {
  return Deno.env.get("GEMINI_API_KEY") ?? "";
}

/**
 * Server-side GEMINI_API_KEY only (BYOK headers removed — M1).
 */
function resolveGeminiKey(): string {
  return getServerGeminiKey().trim();
}

function sanitizePrompt(input: string, maxLength = MAX_PROMPT_LENGTH): string {
  return String(input ?? "")
    .replace(/[\u0000-\u0008]/g, "")
    .replace(/[\u000E-\u001F]/g, "")
    .slice(0, maxLength)
    .trim();
}

function sanitizeSystemPrompt(input: string): string {
  return sanitizePrompt(input, MAX_SYSTEM_PROMPT_LENGTH);
}

function sanitizeModel(input: string | undefined, fallback = DEFAULT_MODEL): string {
  const model = String(input ?? "").trim();

  if (!model) {
    return fallback;
  }

  // Only allow known-safe Gemini model ID patterns.
  if (!/^gemini-[a-z0-9.-]+$/i.test(model)) {
    return fallback;
  }

  return model;
}

function clampNumber(value: number, min: number, max: number, fallback: number): number {
  if (!Number.isFinite(value)) {
    return fallback;
  }

  return Math.min(max, Math.max(min, value));
}

function normalizeTemperature(value: number): number {
  return clampNumber(value, 0, 2, 0.7);
}

function normalizeMaxTokens(value: number): number {
  return Math.floor(clampNumber(value, 1, 8192, 2048));
}

function extractTextFromGemini(data: unknown): string {
  const response = data as GeminiResponse;
  const parts = response.candidates?.[0]?.content?.parts;

  if (!Array.isArray(parts)) {
    return "";
  }

  return parts
    .map((part) => (typeof part.text === "string" ? part.text : ""))
    .filter(Boolean)
    .join("");
}

function truncateErrorText(value: string): string {
  if (value.length <= MAX_ERROR_TEXT_LENGTH) {
    return value;
  }

  return `${value.slice(0, MAX_ERROR_TEXT_LENGTH)}...[truncated]`;
}

function buildGeminiUrl(model: string, method: "generateContent" | "streamGenerateContent"): string {
  return `${GEMINI_BASE}/models/${model}:${method}`;
}

/**
 * Returns Gemini SSE URL for streaming callers.
 */
export function buildGeminiStreamUrl(model?: string): string {
  const safeModel = sanitizeModel(model);

  return `${buildGeminiUrl(safeModel, "streamGenerateContent")}?alt=sse`;
}

async function geminiRequest(
  payload: Record<string, unknown>,
  options: GeminiRequestOptions = {}
): Promise<unknown> {
  const apiKey = resolveGeminiKey();

  if (!apiKey) {
    throw new Error(
      "No Gemini API key available. Set GEMINI_API_KEY in Supabase Secrets."
    );
  }

  const model = sanitizeModel(options.model);
  const method = options.stream ? "streamGenerateContent" : "generateContent";
  const timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS;

  const maxAttempts = 4;
  let lastError: Error | null = null;

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    const controller = new AbortController();
    const timer = setTimeout(() => {
      controller.abort();
    }, timeoutMs);

    try {
      const response = await fetch(buildGeminiUrl(model, method), {
        method: "POST",
        signal: controller.signal,
        headers: {
          "Content-Type": "application/json",
          "x-goog-api-key": apiKey,
        },
        body: JSON.stringify(payload),
      });

      if (response.ok) {
        return await response.json();
      }

      const errorText = await response
        .text()
        .catch(() => "Unknown Gemini error");

      lastError = new Error(
        `Gemini API error (${response.status}): ${truncateErrorText(errorText)}`
      );

      if (
        (response.status === 429 || response.status === 503) &&
        attempt < maxAttempts - 1
      ) {
        const waitMs = Math.min(12_000, 1500 * 2 ** attempt);
        await new Promise((r) => setTimeout(r, waitMs));
        continue;
      }

      throw lastError;
    } catch (error) {
      if (error instanceof Error && error.name === "AbortError") {
        throw new Error(`Gemini request timed out after ${timeoutMs}ms.`);
      }
      throw error;
    } finally {
      clearTimeout(timer);
    }
  }

  throw lastError ?? new Error("Gemini request failed");
}

/* -------------------------------------------------------------------------- */
/*                         GENERATE MODE                                      */
/* -------------------------------------------------------------------------- */

export async function geminiGenerate(
  prompt: string,
  systemPrompt?: string,
  temperature = 0.7,
  maxTokens = 2048,
  model?: string
): Promise<string> {
  const safePrompt = sanitizePrompt(prompt);
  const safeSystemPrompt = systemPrompt
    ? sanitizeSystemPrompt(systemPrompt)
    : undefined;

  const payload: Record<string, unknown> = {
    contents: [
      {
        role: "user",
        parts: [
          {
            text: safePrompt,
          },
        ],
      },
    ],
    generationConfig: {
      temperature: normalizeTemperature(temperature),
      maxOutputTokens: normalizeMaxTokens(maxTokens),
    },
  };

  if (safeSystemPrompt) {
    payload.systemInstruction = {
      parts: [
        {
          text: safeSystemPrompt,
        },
      ],
    };
  }

  const data = await geminiRequest(payload, {
    model,
  });

  return extractTextFromGemini(data);
}

/** Generate from text + inline PDF (base64) using shared Gemini auth + default model. */
export async function geminiGenerateWithPdf(
  prompt: string,
  pdfBase64: string,
  options?: { temperature?: number; maxTokens?: number; model?: string }
): Promise<string> {
  const safePrompt = sanitizePrompt(prompt, MAX_PROMPT_LENGTH);
  const payload: Record<string, unknown> = {
    contents: [
      {
        role: "user",
        parts: [
          { text: safePrompt },
          {
            inlineData: {
              mimeType: "application/pdf",
              data: pdfBase64,
            },
          },
        ],
      },
    ],
    generationConfig: {
      temperature: normalizeTemperature(options?.temperature ?? 0.2),
      maxOutputTokens: normalizeMaxTokens(options?.maxTokens ?? 4096),
    },
  };

  const data = await geminiRequest(payload, {
    model: options?.model,
    timeoutMs: 60_000,
  });

  return extractTextFromGemini(data);
}

/* -------------------------------------------------------------------------- */
/*                             CHAT MODE                                      */
/* -------------------------------------------------------------------------- */

export async function geminiChat(
  messages: GeminiMessage[],
  systemPrompt?: string,
  temperature = 0.7,
  maxTokens = 1024,
  model?: string
): Promise<string> {
  const safeMessages = messages
    .filter((message) => message.role === "user" || message.role === "model")
    .map((message) => ({
      role: message.role,
      parts: (message.parts ?? [])
        .map((part) => ({
          text: sanitizePrompt(part.text),
        }))
        .filter((part) => part.text.length > 0),
    }))
    .filter((message) => message.parts.length > 0);

  const payload: Record<string, unknown> = {
    contents: safeMessages,
    generationConfig: {
      temperature: normalizeTemperature(temperature),
      maxOutputTokens: normalizeMaxTokens(maxTokens),
    },
  };

  if (systemPrompt) {
    payload.systemInstruction = {
      parts: [
        {
          text: sanitizeSystemPrompt(systemPrompt),
        },
      ],
    };
  }

  const data = await geminiRequest(payload, {
    model,
  });

  return extractTextFromGemini(data);
}

/* -------------------------------------------------------------------------- */
/*                       ROBUST JSON PARSER FOR GEMINI                         */
/* -------------------------------------------------------------------------- */

function tryParseJson<T>(value: string): T | null {
  try {
    return JSON.parse(value) as T;
  } catch {
    return null;
  }
}

function extractJsonCandidates(input: string): string[] {
  const candidates: string[] = [];

  const fenceRegex = /```(?:json)?\s*([\s\S]*?)```/gi;
  let block: RegExpExecArray | null;

  while ((block = fenceRegex.exec(input)) !== null) {
    const candidate = block[1]?.trim();

    if (candidate) {
      candidates.push(candidate);
    }
  }

  const firstObjectIndex = input.indexOf("{");
  const lastObjectIndex = input.lastIndexOf("}");

  if (
    firstObjectIndex !== -1 &&
    lastObjectIndex !== -1 &&
    lastObjectIndex > firstObjectIndex
  ) {
    candidates.push(input.slice(firstObjectIndex, lastObjectIndex + 1));
  }

  const firstArrayIndex = input.indexOf("[");
  const lastArrayIndex = input.lastIndexOf("]");

  if (
    firstArrayIndex !== -1 &&
    lastArrayIndex !== -1 &&
    lastArrayIndex > firstArrayIndex
  ) {
    candidates.push(input.slice(firstArrayIndex, lastArrayIndex + 1));
  }

  candidates.push(input.trim());

  return candidates;
}

export function parseJSON<T>(raw: string, fallback: T): T {
  if (!raw || raw.trim().length === 0) {
    return fallback;
  }

  const input = raw.trim();
  const candidates = extractJsonCandidates(input);

  for (let index = candidates.length - 1; index >= 0; index -= 1) {
    const parsed = tryParseJson<T>(candidates[index]);

    if (parsed !== null) {
      return parsed;
    }
  }

  console.warn("[gemini] parseJSON failed. Raw snippet:", input.slice(0, 200));

  return fallback;
}
//
// SECURITY PURPOSE:
// - Centralize Gemini API calls
// - Support server-side Gemini key and BYOK Gemini key

// supabase/functions/_shared/aiProvider.ts
//
// AI Provider abstraction with automatic fallback.
// Primary: Gemini 2.0 Flash
// Fallback: Gemini 1.5 Pro (if Flash fails or is rate-limited)
//
// Includes:
// - Retry with exponential backoff on transient errors
// - Model fallback routing
// - Token/length limit handling per content type
// - Output content moderation
// - Non-blocking cost logging to ai_usage_logs

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2.45.4";
import { callAI } from "./utils.ts";
import type { ModelId } from "./types.ts";
import { getFallbackModels } from "./resolveModel.ts";

const GEMINI_API_VERSION = Deno.env.get("GEMINI_API_VERSION") ?? "v1beta";
const GEMINI_BASE = `https://generativelanguage.googleapis.com/${GEMINI_API_VERSION}`;

/* -------------------------------------------------------------------------- */
/*                                  TYPES                                     */
/* -------------------------------------------------------------------------- */

export interface AIProviderOptions {
  prompt: string;
  systemPrompt?: string;
  maxTokens?: number;
  temperature?: number;
  userId: string;
  action: string;
  jsonMode?: boolean;
  /** API model id (e.g. gpt-4o, gemini-2.0-flash). Falls back to Gemini chain if omitted. */
  model?: string;
  /** @deprecated M1 — BYOK ignored; server keys only. */
  byok?: Record<string, never>;
}

export interface AIProviderResult {
  text: string;
  provider: string;
  model: string;
  inputTokens: number;
  outputTokens: number;
  latencyMs: number;
  wasFallback: boolean;
}

/* -------------------------------------------------------------------------- */
/*                                 CONSTANTS                                  */
/* -------------------------------------------------------------------------- */

const MODELS = {
  primary: "gemini-2.5-flash",
  fallback: "gemini-flash-latest",
} as const;

const MAX_RETRIES = 2;
const RETRY_DELAY_MS = 1_000;
const REQUEST_TIMEOUT_MS = 50_000;

const CHARS_PER_TOKEN = 4;

export const TOKEN_LIMITS = {
  resumeContext: 8_000,
  jdContext: 4_000,
  chatHistory: 6_000,
  userQuestion: 2_000,
} as const;

const COST_PER_MILLION_INPUT: Record<string, number> = {
  "gemini-2.0-flash": 10,
  "gemini-1.5-pro": 125,
  "gemini-2.5-flash": 10,
  "gpt-4o": 250,
  "gpt-4o-mini": 15,
  "claude-3-5-sonnet-20241022": 300,
  "claude-3-haiku-20240307": 25,
};

const COST_PER_MILLION_OUTPUT: Record<string, number> = {
  "gemini-2.0-flash": 40,
  "gemini-1.5-pro": 500,
  "gemini-2.5-flash": 40,
  "gpt-4o": 1000,
  "gpt-4o-mini": 60,
  "claude-3-5-sonnet-20241022": 1500,
  "claude-3-haiku-20240307": 125,
};

/* -------------------------------------------------------------------------- */
/*                          GEMINI RAW REQUEST                                */
/* -------------------------------------------------------------------------- */

type GeminiCandidatePart = { text?: string };
type GeminiCandidateContent = { parts?: GeminiCandidatePart[] };
type GeminiCandidate = { content?: GeminiCandidateContent };
type GeminiUsageMetadata = {
  promptTokenCount?: number;
  candidatesTokenCount?: number;
  totalTokenCount?: number;
};
type GeminiResponse = {
  candidates?: GeminiCandidate[];
  usageMetadata?: GeminiUsageMetadata;
};

function getGeminiKey(): string {
  const key = Deno.env.get("GEMINI_API_KEY") ?? "";
  if (!key) {
    throw new Error("GEMINI_API_KEY is not configured.");
  }
  return key;
}

function extractText(data: GeminiResponse): string {
  const parts = data.candidates?.[0]?.content?.parts;
  if (!Array.isArray(parts)) return "";
  return parts
    .map((p) => (typeof p.text === "string" ? p.text : ""))
    .filter(Boolean)
    .join("");
}

function isRetryableStatus(status: number): boolean {
  return status === 429 || status >= 500;
}

async function callGemini(
  model: string,
  prompt: string,
  systemPrompt: string | undefined,
  temperature: number,
  maxTokens: number,
  jsonMode: boolean
): Promise<{ response: GeminiResponse; status: number }> {
  const apiKey = getGeminiKey();
  const url = `${GEMINI_BASE}/models/${model}:generateContent`;

  const payload: Record<string, unknown> = {
    contents: [{ role: "user", parts: [{ text: prompt }] }],
    generationConfig: {
      temperature,
      maxOutputTokens: maxTokens,
      ...(jsonMode ? { responseMimeType: "application/json" } : {}),
    },
  };

  if (systemPrompt) {
    payload.systemInstruction = { parts: [{ text: systemPrompt }] };
  }

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);

  try {
    const res = await fetch(url, {
      method: "POST",
      signal: controller.signal,
      headers: {
        "Content-Type": "application/json",
        "x-goog-api-key": apiKey,
      },
      body: JSON.stringify(payload),
    });

    if (!res.ok) {
      const errorText = await res.text().catch(() => "Unknown error");
      if (isRetryableStatus(res.status)) {
        return { response: {} as GeminiResponse, status: res.status };
      }
      throw new Error(
        `Gemini API error (${res.status}): ${errorText.slice(0, 500)}`
      );
    }

    const data = (await res.json()) as GeminiResponse;
    return { response: data, status: res.status };
  } catch (err) {
    if (err instanceof Error && err.name === "AbortError") {
      throw new Error(`Gemini request timed out after ${REQUEST_TIMEOUT_MS}ms.`);
    }
    throw err;
  } finally {
    clearTimeout(timer);
  }
}

/* -------------------------------------------------------------------------- */
/*                        GENERATE WITH FALLBACK                              */
/* -------------------------------------------------------------------------- */

function isQuotaOrRateLimitError(err: Error): boolean {
  const msg = err.message.toLowerCase();
  return (
    msg.includes("429") ||
    msg.includes("quota") ||
    msg.includes("rate limit") ||
    msg.includes("resource_exhausted")
  );
}

export async function generateWithFallback(
  options: AIProviderOptions
): Promise<AIProviderResult> {
  const {
    prompt,
    systemPrompt,
    maxTokens = 2048,
    temperature = 0.7,
    jsonMode = false,
    model: requestedModel,
  } = options;

  const models = getFallbackModels(requestedModel ?? MODELS.primary);
  let lastError: Error | null = null;
  let skipGeminiFamily = false;

  for (let i = 0; i < models.length; i++) {
    const model = models[i];
    const isGemini = model.startsWith("gemini");
    if (skipGeminiFamily && isGemini) continue;

    const isFallback = i > 0;
    // Quota errors rarely recover within a few seconds — one retry max.
    const attempts = isGemini ? 1 : MAX_RETRIES;

    for (let attempt = 0; attempt <= attempts; attempt++) {
      if (attempt > 0) {
        await new Promise((r) => setTimeout(r, RETRY_DELAY_MS * attempt));
      }

      const startMs = Date.now();

      try {
        const userContent = jsonMode
          ? `${prompt}\n\nRespond with valid JSON only.`
          : prompt;

        const messages: Array<{ role: "system" | "user"; content: string }> = [];
        if (systemPrompt) {
          messages.push({ role: "system", content: systemPrompt });
        }
        messages.push({ role: "user", content: userContent });

        const result = await callAI(
          {
            model: model as ModelId,
            messages,
            maxTokens,
            temperature,
            stream: false,
            jsonMode,
          },
        );

        if (!result.text || !result.text.trim()) {
          throw new Error(`Model ${model} returned an empty response`);
        }

        const provider = model.startsWith("gpt")
          ? "openai"
          : model.startsWith("claude")
            ? "anthropic"
            : "gemini";

        return {
          text: result.text,
          provider,
          model: result.model,
          inputTokens: result.tokensIn,
          outputTokens: result.tokensOut,
          latencyMs: Date.now() - startMs,
          wasFallback: isFallback,
        };
      } catch (err) {
        lastError = err instanceof Error ? err : new Error(String(err));
        if (isGemini && isQuotaOrRateLimitError(lastError)) {
          // Gemini project quota is shared across models — jump to OpenAI/Anthropic.
          skipGeminiFamily = true;
          break;
        }
        if (attempt < attempts) continue;
        break;
      }
    }
  }

  throw new Error(
    `All AI models failed. Last error: ${lastError?.message ?? "Unknown"}`
  );
}

/* -------------------------------------------------------------------------- */
/*                      TOKEN / LENGTH LIMIT HANDLING                         */
/* -------------------------------------------------------------------------- */

export function truncateToTokenLimit(text: string, maxTokens: number): string {
  const maxChars = maxTokens * CHARS_PER_TOKEN;
  if (text.length <= maxChars) return text;
  return text.slice(0, maxChars) + "\n\n[Content truncated to fit token limits]";
}

export function truncateResumeContext(text: string): string {
  return truncateToTokenLimit(text, TOKEN_LIMITS.resumeContext);
}

export function truncateJdContext(text: string): string {
  return truncateToTokenLimit(text, TOKEN_LIMITS.jdContext);
}

export function truncateUserQuestion(text: string): string {
  return truncateToTokenLimit(text, TOKEN_LIMITS.userQuestion);
}

/**
 * Truncate chat history to fit within token limits, keeping the most recent
 * messages. Each message is estimated at its character length / CHARS_PER_TOKEN.
 */
export function truncateChatHistory<T extends { text?: string; content?: string }>(
  messages: T[],
  maxTokens: number = TOKEN_LIMITS.chatHistory
): T[] {
  const maxChars = maxTokens * CHARS_PER_TOKEN;
  const result: T[] = [];
  let totalChars = 0;

  for (let i = messages.length - 1; i >= 0; i--) {
    const msg = messages[i];
    const content = msg.text ?? msg.content ?? "";
    const charCount = content.length;

    if (totalChars + charCount > maxChars) break;
    totalChars += charCount;
    result.unshift(msg);
  }

  return result;
}

/* -------------------------------------------------------------------------- */
/*                         OUTPUT CONTENT MODERATION                          */
/* -------------------------------------------------------------------------- */

export interface ModerationResult {
  safe: boolean;
  filtered: string;
  reason?: string;
}

const BLOCKED_PATTERNS = [
  /hide\s+this\s+from\s+(the\s+)?interviewer/i,
  /don't\s+tell\s+(the\s+)?interviewer/i,
  /cheat\s+on\s+(the\s+)?(interview|exam|test|assessment)/i,
  /pretend\s+you\s+(did|have|know)/i,
  /fabricate\s+(your|a|the)\s+(experience|credential|degree)/i,
  /lie\s+to\s+(the\s+)?interviewer/i,
  /social\s+security\s+number/i,
  /credit\s+card\s+number/i,
  /\b\d{3}-\d{2}-\d{4}\b/,
];

export function moderateOutput(text: string): ModerationResult {
  for (const pattern of BLOCKED_PATTERNS) {
    if (pattern.test(text)) {
      return {
        safe: false,
        filtered: "[Response filtered for compliance]",
        reason: "compliance_violation",
      };
    }
  }

  return { safe: true, filtered: text };
}

/* -------------------------------------------------------------------------- */
/*                           COST TRACKING                                    */
/* -------------------------------------------------------------------------- */

function estimateCostMicrocents(
  model: string,
  inputTokens: number,
  outputTokens: number
): number {
  const inputRate = COST_PER_MILLION_INPUT[model] ?? 10;
  const outputRate = COST_PER_MILLION_OUTPUT[model] ?? 40;
  const inputCost = (inputTokens / 1_000_000) * inputRate * 100_000;
  const outputCost = (outputTokens / 1_000_000) * outputRate * 100_000;
  return Math.round(inputCost + outputCost);
}

export async function logAICost(
  supabaseAdmin: SupabaseClient,
  params: {
    userId: string;
    action: string;
    model: string;
    inputTokens: number;
    outputTokens: number;
    latencyMs: number;
    wasFallback: boolean;
  }
): Promise<void> {
  try {
    const costMicrocents = estimateCostMicrocents(
      params.model,
      params.inputTokens,
      params.outputTokens
    );

    await supabaseAdmin.from("ai_usage_logs").insert({
      user_id: params.userId,
      action: params.action,
      model: params.model,
      input_tokens: params.inputTokens,
      output_tokens: params.outputTokens,
      latency_ms: params.latencyMs,
      was_fallback: params.wasFallback,
      cost_microcents: costMicrocents,
    });
  } catch (err) {
    console.error(
      "[aiProvider] Failed to log AI cost:",
      err instanceof Error ? err.message : String(err)
    );
  }
}

