export function getAdminClient(): SupabaseClient {
  if (!ENV.SUPABASE_URL || !ENV.SUPABASE_SERVICE_KEY) {
    throw new Error("[utils] Cannot create admin client: missing SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY.");
  }
  return createClient(ENV.SUPABASE_URL, ENV.SUPABASE_SERVICE_KEY, {
    auth: { persistSession: false }
  });
}

/* -------------------------------------------------------------------------- */
/*                         AUTH (BYOK headers removed — M1)                    */
/* -------------------------------------------------------------------------- */

export async function requireAuth(req: Request): Promise<AuthContext> {
  if (!ENV.SUPABASE_URL || !ENV.SUPABASE_ANON_KEY) {
    throw errorResponse(
      "Server misconfiguration: missing Supabase credentials.",
      "INTERNAL_ERROR",
      500,
      req
    );
  }

  const header = req.headers.get("Authorization");
  if (!header?.startsWith("Bearer ")) {
    throw errorResponse("Missing or invalid Authorization header", "AUTH_REQUIRED", 401, req);
  }

  const token = header.slice(7);

  const client = createClient(ENV.SUPABASE_URL, ENV.SUPABASE_ANON_KEY, {
    global: { headers: { Authorization: `Bearer ${token}` } },
    auth: { persistSession: false }
  });

  const { data: { user }, error } = await client.auth.getUser();
  if (error || !user) {
    throw errorResponse("Invalid or expired token", "AUTH_INVALID", 401, req);
  }

  const admin = getAdminClient();

  const { data: profile, error: profileError } = await admin
    .from("profiles")
    .select("plan_id, credits, is_banned, subscription_status, payment_failed_at")
    .eq("id", user.id)
    .maybeSingle();

  // Fail closed on ban-lookup errors so a transient DB outage cannot bypass suspension.
  if (profileError) {
    console.error("[utils.requireAuth] profile ban lookup failed:", profileError.message);
    throw errorResponse(
      "Account suspended. Contact support.",
      "ACCOUNT_BANNED",
      403,
      req
    );
  }

  if (profile?.is_banned) {
    throw errorResponse(
      "Account suspended. Contact support.",
      "ACCOUNT_BANNED",
      403,
      req
    );
  }

  if (
    !isPastDueAllowedPath(req) &&
    isBillingPastDue(profile as {
      subscription_status?: string | null;
      payment_failed_at?: string | null;
    })
  ) {
    throw errorResponse(
      "Payment failed. Update your payment method to keep using AI features.",
      "BILLING_PAST_DUE",
      403,
      req
    );
  }

  const { data: roleRow } = await admin
    .from("user_roles")
    .select("role")
    .eq("user_id", user.id)
    .eq("role", "admin")
    .maybeSingle();

  return {
    userId: user.id,
    email: user.email ?? "",
    planId: profile?.plan_id ?? "free",
    credits: profile?.credits ?? 0,
    isAdmin: !!roleRow,
  };
}

