/* -------------------------------------------------------------------------- */

export function successResponse<T>(
  data: T,
  meta?: EdgeSuccess<T>["meta"],
  status = 200,
  req?: Request
): Response {
  const correlationId = req ? resolveCorrelationId(req) : undefined;
  const response = new Response(
    JSON.stringify({
      success: true,
      data,
      ...(meta ? { meta } : {}),
      ...(correlationId ? { correlation_id: correlationId, correlationId } : {}),
    }),
    {
      status,
      headers: {
        "Content-Type": "application/json",
        "Cache-Control": "no-store",
        ...safeCorsHeaders(req),
      },
    },
  );
  return req ? applyCors(req, response, correlationId) : response;
}

export function errorResponse(
  message: string,
  code = "INTERNAL_ERROR",
  status = 500,
  req?: Request
): Response {
  const correlationId = req ? resolveCorrelationId(req) : undefined;
  const response = new Response(
    JSON.stringify({
      success: false,
      error: message,
      code,
      ...(correlationId ? { correlation_id: correlationId, correlationId } : {}),
    }),
    {
      status,
      headers: {
        "Content-Type": "application/json",
        "Cache-Control": "no-store",
        ...safeCorsHeaders(req),
      },
    },
  );
  return req ? applyCors(req, response, correlationId) : response;
}

export function streamResponse(stream: ReadableStream, req?: Request): Response {
  const response = new Response(stream, {
    headers: {
      ...safeCorsHeaders(req),
      "Content-Type": "text/event-stream",
      "Cache-Control": "no-cache",
      Connection: "keep-alive",
    },
  });
  return req ? applyCors(req, response) : response;
}

