/* -------------------------------------------------------------------------- */

// Updated provider map with modern Gemini 2.5 models (recommended) 【1-c30e89】
const PROVIDER_MAP: Record<string, "openai" | "anthropic" | "gemini"> = {
  // OpenAI
  "gpt-4o": "openai",
  "gpt-4o-mini": "openai",
  "gpt-4-turbo": "openai",

  // Anthropic
  "claude-3-5-sonnet-20241022": "anthropic",
  "claude-3-haiku-20240307": "anthropic",

  // Gemini (modern + legacy)
  "gemini-2.5-flash": "gemini",
  "gemini-2.5-pro": "gemini",
  "gemini-2.5-flash-lite": "gemini",
  "gemini-2.0-flash": "gemini",
  "gemini-2.0-flash-lite": "gemini",
  "gemini-flash-latest": "gemini",
  "gemini-1.5-flash": "gemini",
  "gemini-1.5-pro": "gemini",
};

export async function callAI(
  req: AICompletionRequest,
): Promise<AICompletionResponse> {
  const start = Date.now();
  const provider = PROVIDER_MAP[req.model];

  if (provider === "openai") return callOpenAI(req, start);
  if (provider === "anthropic") return callAnthropic(req, start);
  if (provider === "gemini") return callGemini(req, start);

  throw new Error(
    `Unknown model provider for "${req.model}". Add it to PROVIDER_MAP in utils.ts.`
  );
}

const AI_TIMEOUT_MS = 50_000;

/* ------------------------------- OpenAI ----------------------------------- */

async function callOpenAI(
  req: AICompletionRequest,
  start: number,
): Promise<AICompletionResponse> {
  const apiKey = ENV.OPENAI_API_KEY;
  if (!apiKey) {
    throw new Error("OpenAI API key not available. Set OPENAI_API_KEY in Supabase Secrets.");
  }

  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), AI_TIMEOUT_MS);

  let res: Response;
  try {
    res = await fetch("https://api.openai.com/v1/chat/completions", {
      method: "POST",
      signal: ctrl.signal,
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${apiKey}`
      },
      body: JSON.stringify({
        model: req.model,
        messages: req.messages,
        max_tokens: req.maxTokens ?? 1024,
        temperature: req.temperature ?? 0.7,
        stream: req.stream ?? false,
        ...(req.jsonMode ? { response_format: { type: "json_object" } } : {}),
      })
    });
  } finally {
    clearTimeout(timer);
  }

  if (!res.ok) {
    const errText = await res.text().catch(() => "Unknown OpenAI error");
    throw new Error(`OpenAI error ${res.status}: ${errText}`);
  }

  const json = await res.json();
  const choice = json.choices?.[0];
  const text = choice?.message?.content ?? "";
  const usage = json.usage ?? {};

  return {
    text,
    model: req.model,
    tokensIn: usage.prompt_tokens ?? 0,
    tokensOut: usage.completion_tokens ?? 0,
    totalTokens: usage.total_tokens ?? 0,
    latencyMs: Date.now() - start
  };
}

/* ------------------------------ Anthropic --------------------------------- */

async function callAnthropic(
  req: AICompletionRequest,
  start: number,
): Promise<AICompletionResponse> {
  const apiKey = ENV.ANTHROPIC_API_KEY;
  if (!apiKey) {
    throw new Error("Anthropic API key not available. Set ANTHROPIC_API_KEY in Supabase Secrets.");
  }

  const system = req.messages.find(m => m.role === "system")?.content ?? "";
  const userMessages = req.messages.filter(m => m.role !== "system");

  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), AI_TIMEOUT_MS);

  let res: Response;
  try {
    res = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      signal: ctrl.signal,
      headers: {
        "Content-Type": "application/json",
        "x-api-key": apiKey,
        "anthropic-version": "2023-06-01"
      },
      body: JSON.stringify({
        model: req.model,
        max_tokens: req.maxTokens ?? 1024,
        system,
        messages: userMessages
      })
    });
  } finally {
    clearTimeout(timer);
  }

  if (!res.ok) {
    const errText = await res.text().catch(() => "Unknown Anthropic error");
    throw new Error(`Anthropic error ${res.status}: ${errText}`);
  }

  const json = await res.json();
  const content = json.content?.[0]?.text ?? "";
  const usage = json.usage ?? {};

  return {
    text: content,
    model: req.model,
    tokensIn: usage.input_tokens ?? 0,
    tokensOut: usage.output_tokens ?? 0,
    totalTokens: (usage.input_tokens ?? 0) + (usage.output_tokens ?? 0),
    latencyMs: Date.now() - start
  };
}

/* -------------------------------- Gemini ---------------------------------- */

function extractGeminiText(json: any): string {
  const parts = json?.candidates?.[0]?.content?.parts ?? [];
  if (!Array.isArray(parts)) return "";
  return parts.map((p: any) => p?.text ?? "").join("");
}

async function callGemini(
  req: AICompletionRequest,
  start: number,
): Promise<AICompletionResponse> {
  const apiKey = ENV.GEMINI_API_KEY;
  if (!apiKey) {
    throw new Error("Gemini API key not available. Set GEMINI_API_KEY in Supabase Secrets.");
  }

  const base = `https://generativelanguage.googleapis.com/${ENV.GEMINI_API_VERSION}`;

  // Convert OpenAI-style messages to Gemini contents.
  // Gemini supports "user" and "model" roles; keep system separate.
  const system = req.messages.filter(m => m.role === "system").map(m => ({ text: m.content }));
  const contents = req.messages
    .filter(m => m.role !== "system")
    .map(m => ({
      role: m.role === "assistant" ? "model" : "user",
      parts: [{ text: m.content }]
    }));

  const body: Record<string, unknown> = {
    contents,
    generationConfig: {
      maxOutputTokens: req.maxTokens ?? 1024,
      temperature: req.temperature ?? 0.7,
      ...(req.jsonMode ? { responseMimeType: "application/json" } : {}),
    }
  };

  if (system.length > 0) {
    body.systemInstruction = { parts: system };
  }

  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), AI_TIMEOUT_MS);

  let res: Response;
  try {
    // Use header-based key auth (recommended in streaming examples too) 【2-a9b3ed】
    res = await fetch(`${base}/models/${req.model}:generateContent`, {
      method: "POST",
      signal: ctrl.signal,
      headers: {
        "Content-Type": "application/json",
        "x-goog-api-key": apiKey,
      },
      body: JSON.stringify(body)
    });
  } finally {
    clearTimeout(timer);
  }

  if (!res.ok) {
    const errText = await res.text().catch(() => "Unknown Gemini error");
    throw new Error(`Gemini error ${res.status}: ${errText}`);
  }

  const json = await res.json();
  const text = extractGeminiText(json);
  const usage = json.usageMetadata ?? {};

  return {
    text,
    model: req.model,
    tokensIn: usage.promptTokenCount ?? 0,
    tokensOut: usage.candidatesTokenCount ?? 0,
    totalTokens: usage.totalTokenCount ?? 0,
    latencyMs: Date.now() - start
  };
}

