export function normalizePlanId(
  raw: string | null | undefined,
): CanonicalPlanId | null {
  if (raw == null) return "free";
  const key = String(raw).trim().toLowerCase();
  if (!key) return "free";
  return ALIASES[key] ?? null;
}

export function toLaunchPlanId(
  raw: string | null | undefined,
): LaunchPlanId {
  const id = normalizePlanId(raw);
  if (id === "enterprise") return "enterprise";
  if (id === "pro" || id === "elite") return "pro";
  return "free";
}

export function planRank(raw: string | null | undefined): number {
  const id = normalizePlanId(raw);
  if (!id) return -1;
  return PLAN_RANK[id];
}

/** Authorization rank: legacy starter is Free; elite is Pro. */
export function launchPlanRank(raw: string | null | undefined): number {
  return PLAN_RANK[toLaunchPlanId(raw)];
}

export function getPlanDisplayName(raw: string | null | undefined): string {
  const id = normalizePlanId(raw) ?? "free";
  return PLAN_CATALOG[id].displayName;
}

export function monthlyCreditsForPlan(
  raw: string | null | undefined,
): number {
  const id = normalizePlanId(raw) ?? "free";
  return PLAN_CATALOG[id].monthlyCredits;
}

/**
 * Server-owned credit amount for a Razorpay product_type.
 * Never trust client or payment_orders.credits_granted for grants.
 */
export function creditsForRazorpayProductType(productType: string): number {
  const key = productType.trim();
  const plan = Object.values(PLAN_CATALOG).find((p) =>
    p.razorpayProductIds?.includes(key)
  );
  if (plan) return plan.monthlyCredits;

  const pack = CREDIT_PACK_CATALOG.find((p) => p.packId === key && p.active);
  return pack?.credits ?? 0;
}

/** Plan id for Razorpay subscription products; null for credit packs. */
export function planIdForRazorpayProductType(
  productType: string,
): CanonicalPlanId | null {
  const key = productType.trim();
  const plan = Object.values(PLAN_CATALOG).find((p) =>
    p.razorpayProductIds?.includes(key)
  );
  return plan?.planId ?? null;
}

/** Blueprint construction for create-exam-paper (mirrors src/lib/gov-exam/blueprintEngine.ts). */

export interface PatternSection {
  code: string;
  name: string;
  question_count: number;
  marks: number;
}

export interface PatternVersion {
  id: string;
  version: string;
  total_questions: number;
  total_marks: number;
  duration_minutes: number;
  negative_mark: number;
  marks_per_question: number;
  languages: string[];
  sections: PatternSection[];
}

export interface BlueprintSlot {
  section_code: string;
  difficulty: "easy" | "medium" | "hard" | "exam_balanced";
  question_type: "single_mcq";
}

export interface PaperBlueprint {
  exam_id: string;
  exam_code: string;
  stage_id: string;
  pattern_version_id: string;
  pattern_version: string;
  syllabus_version_id: string | null;
  syllabus_version: string | null;
  language: string;
  total_questions: number;
  total_marks: number;
  duration_minutes: number;
  negative_mark: number;
  marks_per_question: number;
  sections: PatternSection[];
  slots: BlueprintSlot[];
  source_years: number[];
  mode: "official_previous" | "generated_mock" | "custom_mock" | "adaptive";
  paper_class: "official_previous" | "ai_generated" | "custom_practice";
  generation_policy_version: string;
  random_seed: string;
  algorithm_version: string;
  hard_constraints_ok: true;
  label: string;
}

const AI_LABEL =
  "AI-generated practice paper based on the selected syllabus, pattern, and historical topic distribution. This is not an official or leaked examination paper.";

export function buildBlueprint(input: {
  examId: string;
  examCode: string;
  stageId: string;
  pattern: PatternVersion;
  syllabusVersionId?: string | null;
  syllabusVersion?: string | null;
  language: string;
  sourceYears: number[];
  mode: PaperBlueprint["mode"];
  randomSeed: string;
  customQuestionCount?: number | null;
  customDuration?: number | null;
}): PaperBlueprint {
  const pattern = input.pattern;
  const customizing =
    (input.customQuestionCount != null &&
      input.customQuestionCount !== pattern.total_questions) ||
    (input.customDuration != null &&
      input.customDuration !== pattern.duration_minutes) ||
    input.mode === "custom_mock" ||
    input.mode === "adaptive";

  const totalQuestions = customizing
    ? Math.min(
      pattern.total_questions,
      Math.max(5, input.customQuestionCount ?? pattern.total_questions),
    )
    : pattern.total_questions;

  const scale = totalQuestions / pattern.total_questions;
  const sections = pattern.sections.map((s) => ({
    ...s,
    question_count: Math.max(1, Math.round(s.question_count * scale)),
  }));

  const sum = sections.reduce((a, s) => a + s.question_count, 0);
  if (sections.length && sum !== totalQuestions) {
    sections[sections.length - 1].question_count += totalQuestions - sum;
  }

  const slots: BlueprintSlot[] = [];
  for (const section of sections) {
    for (let i = 0; i < section.question_count; i++) {
      slots.push({
        section_code: section.code,
        difficulty: "exam_balanced",
        question_type: "single_mcq",
      });
    }
  }

  const paper_class: PaperBlueprint["paper_class"] =
    input.mode === "official_previous"
      ? "official_previous"
      : customizing
      ? "custom_practice"
      : "ai_generated";

  return {
    exam_id: input.examId,
    exam_code: input.examCode,
    stage_id: input.stageId,
    pattern_version_id: pattern.id,
    pattern_version: pattern.version,
    syllabus_version_id: input.syllabusVersionId ?? null,
    syllabus_version: input.syllabusVersion ?? null,
    language: input.language,
    total_questions: totalQuestions,
    total_marks: customizing
      ? totalQuestions * pattern.marks_per_question
      : pattern.total_marks,
    duration_minutes: input.customDuration ?? pattern.duration_minutes,
    negative_mark: pattern.negative_mark,
    marks_per_question: pattern.marks_per_question,
    sections,
    slots,
    source_years: input.sourceYears,
    mode: input.mode,
    paper_class,
    generation_policy_version: "gov_paper_v1",
    random_seed: input.randomSeed,
    algorithm_version: "recency_v1",
    hard_constraints_ok: true,
    label: paper_class === "ai_generated"
      ? AI_LABEL
      : paper_class === "custom_practice"
      ? "Custom Practice Set — not a full official exam simulation."
      : "Previous-year style practice assembled from approved bank items with provenance.",
  };
}

export function validateBlueprintHardConstraints(
  blueprint: PaperBlueprint,
): { ok: true } | { ok: false; errors: string[] } {
  const errors: string[] = [];
  const sectionSum = blueprint.sections.reduce((a, s) => a + s.question_count, 0);
  if (sectionSum !== blueprint.total_questions) {
    errors.push(`Section question sum ${sectionSum} != total ${blueprint.total_questions}`);
  }
  if (blueprint.slots.length !== blueprint.total_questions) {
    errors.push(`Slots ${blueprint.slots.length} != total ${blueprint.total_questions}`);
  }
  if (blueprint.total_questions < 1) errors.push("total_questions must be >= 1");
  if (blueprint.duration_minutes < 1) errors.push("duration_minutes must be >= 1");
  if (blueprint.negative_mark < 0) errors.push("negative_mark cannot be negative");
  return errors.length ? { ok: false, errors } : { ok: true };
}

export interface AssembledQuestionItem {
  id: string;
  question_text: string;
  options: unknown;
  correct_answer?: unknown;
  section_code?: string | null;
  subject?: string | null;
  topic?: string | null;
}

/**
 * Validates hard constraints on the assembled question list before publication or freezing.
 * Any failure must strictly block publication.
 */
export function validateAssembledPaperHardConstraints(input: {
  blueprint: PaperBlueprint;
  questions: AssembledQuestionItem[];
  aiQuestionIds?: Set<string>;
}): { ok: true } | { ok: false; errors: string[] } {
  const { blueprint, questions } = input;
  const errors: string[] = [];

  // 1. Exact question count
  if (questions.length !== blueprint.total_questions) {
    errors.push(`Exact question count failed: got ${questions.length}, expected ${blueprint.total_questions}`);
  }

  // 2. Exact maximum marks
  const expectedTotalMarks = blueprint.total_questions * blueprint.marks_per_question;
  if (blueprint.total_marks !== expectedTotalMarks) {
    errors.push(`Exact maximum marks failed: blueprint total_marks ${blueprint.total_marks} != calculated ${expectedTotalMarks}`);
  }

  // 3. Supported language
  if (!blueprint.language || blueprint.language.trim().length === 0) {
    errors.push("Paper language must be specified and supported");
  }

  // 4. Positive and negative marks sanity
  if (blueprint.marks_per_question <= 0) {
    errors.push("Marks per question must be greater than zero");
  }
  if (blueprint.negative_mark < 0) {
    errors.push("Negative marking cannot be negative");
  }
  if (blueprint.negative_mark > blueprint.marks_per_question) {
    errors.push("Negative penalty cannot exceed positive marks per question");
  }

  // 5. Duration sanity
  if (blueprint.duration_minutes <= 0) {
    errors.push("Duration minutes must be greater than zero");
  }

  // 6. No duplicate questions
  const seenIds = new Set<string>();
  const seenTexts = new Set<string>();
  for (let i = 0; i < questions.length; i++) {
    const q = questions[i];
    const qid = String(q.id || `idx-${i}`);
    if (seenIds.has(qid)) {
      errors.push(`Duplicate question ID detected: ${qid}`);
    }
    seenIds.add(qid);

    const normText = String(q.question_text || "").trim().toLowerCase().replace(/\s+/g, " ");
    if (normText.length > 10) {
      if (seenTexts.has(normText)) {
        errors.push(`Duplicate question stem detected at position ${i + 1}`);
      }
      seenTexts.add(normText);
    }

    // 7. Valid answer for every question
    if (q.correct_answer == null || String(q.correct_answer).trim() === "") {
      errors.push(`Question at position ${i + 1} (${qid}) has missing or invalid correct_answer`);
    }

    // 8. Options validity
    if (!Array.isArray(q.options) || q.options.length < 2) {
      errors.push(`Question at position ${i + 1} (${qid}) has fewer than 2 options`);
    }
  }

  return errors.length ? { ok: false, errors } : { ok: true };
}

/** Deterministic seeded shuffle (mulberry32). */
export function seededShuffle<T>(items: T[], seed: string): T[] {
  let h = 2166136261;
  for (let i = 0; i < seed.length; i++) {
    h ^= seed.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  let state = h >>> 0;
  const rand = () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  const arr = [...items];
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

// supabase/functions/_shared/auth.ts
//
// Shared authentication and authorization utilities for Supabase Edge Functions.
//
// SECURITY PURPOSE:
// - Verify JWT access tokens using Supabase Auth
// - Extract the authenticated user from requests
// - Provide consistent 401 and 403 responses
// - Centralize ownership/admin checks
// - Prevent every Edge Function from implementing auth differently
//
// REQUIRED ENV SECRETS:
// - SUPABASE_URL
// - SUPABASE_ANON_KEY
// - SUPABASE_SERVICE_ROLE_KEY
//
// IMPORTANT:
// Use service role only for trusted server-side authorization checks.
// Never expose SUPABASE_SERVICE_ROLE_KEY to frontend code.

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { bannedResponse, isUserBanned } from "./banCheck.ts";
import { isBillingPastDue, isPastDueAllowedPath, pastDueResponse, resolveCanonicalBillingStatus } from "./billingPastDue.ts";
import { getCorsHeaders } from "./cors.ts";

export type AuthenticatedUser = {
  id: string;
  email: string | null;
  role: string | null;
  aud: string | null;
};

export type AuthContext = {
  user: AuthenticatedUser;
  accessToken: string;
};

export type UserRole = "user" | "admin" | "super_admin";

const SUPABASE_URL = Deno.env.get("SUPABASE_URL");
const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY");
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");

function assertRequiredEnv(): void {
  const missing: string[] = [];

  if (!SUPABASE_URL) missing.push("SUPABASE_URL");
  if (!SUPABASE_ANON_KEY) missing.push("SUPABASE_ANON_KEY");
  if (!SUPABASE_SERVICE_ROLE_KEY) missing.push("SUPABASE_SERVICE_ROLE_KEY");

  if (missing.length > 0) {
    throw new Error(`[auth] Missing required environment variables: ${missing.join(", ")}`);
  }
}

function jsonResponse(
  body: Record<string, unknown>,
  status: number,
  extraHeaders: Record<string, string> = {}
): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      "Content-Type": "application/json",
      ...extraHeaders,
    },
  });
}

/**
 * Standard 401 Unauthorized response.
 */
export function unauthorizedResponse(message = "Unauthorized.", req?: Request): Response {
  return jsonResponse(
    {
      error: message,
      code: "UNAUTHORIZED",
    },
    401,
    req ? getCorsHeaders(req) : {}
  );
}

/**
 * Standard 403 Forbidden response.
 */
export function forbiddenResponse(message = "Forbidden.", req?: Request): Response {
  return jsonResponse(
    {
      error: message,
      code: "FORBIDDEN",
    },
    403,
    req ? getCorsHeaders(req) : {}
  );
}

/**
 * Extracts Bearer token from Authorization header.
 */
export function extractBearerToken(req: Request): string | null {
  const authHeader = req.headers.get("Authorization");

  if (!authHeader) {
    return null;
  }

  const [scheme, token] = authHeader.split(" ");

  if (scheme !== "Bearer" || !token || token.trim().length === 0) {
    return null;
  }

  return token.trim();
}

/**
 * Creates a Supabase client scoped to the user's JWT.
 *
 * Use this when you want RLS policies to apply.
 */
export function createUserScopedClient(accessToken: string) {
  assertRequiredEnv();

  return createClient(SUPABASE_URL!, SUPABASE_ANON_KEY!, {
    global: {
      headers: {
        Authorization: `Bearer ${accessToken}`,
      },
    },
    auth: {
      persistSession: false,
      autoRefreshToken: false,
      detectSessionInUrl: false,
    },
  });
}

/**
 * Creates a trusted service role Supabase client.
 *
 * Use only inside Edge Functions for server-side authorization checks.
 */
export function createServiceRoleClient() {
  assertRequiredEnv();

  return createClient(SUPABASE_URL!, SUPABASE_SERVICE_ROLE_KEY!, {
    auth: {
      persistSession: false,
      autoRefreshToken: false,
      detectSessionInUrl: false,
    },
  });
}

/**
 * Verifies the incoming request JWT using Supabase Auth.
 *
 * Throws an error if token is missing or invalid.
 * Banned users throw with code ACCOUNT_BANNED (caught by getAuthContext).
 */
export async function requireAuth(req: Request): Promise<AuthContext> {
  const accessToken = extractBearerToken(req);

  if (!accessToken) {
    throw new Error("Missing or invalid Authorization header.");
  }

  const supabase = createUserScopedClient(accessToken);

  const { data, error } = await supabase.auth.getUser(accessToken);

  if (error || !data.user) {
    throw new Error("Invalid or expired access token.");
  }

  const admin = createServiceRoleClient();
  if (await isUserBanned(admin, data.user.id)) {
    const banError = new Error("ACCOUNT_BANNED");
    banError.name = "AccountBannedError";
    throw banError;
  }

  if (!isPastDueAllowedPath(req)) {
    const { data: billing, error: billingError } = await admin
      .from("profiles")
      .select("subscription_status, payment_failed_at")
      .eq("id", data.user.id)
      .maybeSingle();
    const { data: subRow, error: subscriptionError } = await admin
      .from("subscriptions")
      .select("status")
      .eq("user_id", data.user.id)
      .order("updated_at", { ascending: false })
      .limit(1)
      .maybeSingle();
    if (billingError || subscriptionError) {
      console.error("[auth] Billing authorization lookup failed:", {
        billing: billingError?.message,
        subscription: subscriptionError?.message,
      });
      const dependencyError = new Error("Authorization dependency unavailable.");
      dependencyError.name = "DependencyUnavailableError";
      throw dependencyError;
    }
    const effectiveStatus = resolveCanonicalBillingStatus(
      billing?.subscription_status,
      (subRow as { status?: string } | null)?.status,
    );
    if (isBillingPastDue({
      subscription_status: effectiveStatus,
      payment_failed_at: billing?.payment_failed_at,
    })) {
      const dueError = new Error("BILLING_PAST_DUE");
      dueError.name = "BillingPastDueError";
      throw dueError;
    }
  }

  return {
    accessToken,
    user: {
      id: data.user.id,
      email: data.user.email ?? null,
      role: data.user.role ?? null,
      aud: data.user.aud ?? null,
    },
  };
}

/**
 * Safe auth wrapper.
 *
 * Use this when you want a Response instead of throwing.
 */
export async function getAuthContext(
  req: Request
): Promise<{ context: AuthContext; error: null } | { context: null; error: Response }> {
  try {
    const context = await requireAuth(req);

    return {
      context,
      error: null,
    };
  } catch (err) {
    if (
      err instanceof Error &&
      (err.name === "AccountBannedError" || err.message === "ACCOUNT_BANNED")
    ) {
      return {
        context: null,
        error: bannedResponse(getCorsHeaders(req)),
      };
    }
    if (
      err instanceof Error &&
      (err.name === "BillingPastDueError" || err.message === "BILLING_PAST_DUE")
    ) {
      return {
        context: null,
        error: pastDueResponse(getCorsHeaders(req)),
      };
    }
    if (err instanceof Error && err.name === "DependencyUnavailableError") {
      return {
        context: null,
        error: jsonResponse(
          {
            error: "Authorization service temporarily unavailable. Please try again.",
            code: "AUTH_DEPENDENCY_UNAVAILABLE",
          },
          503,
          getCorsHeaders(req),
        ),
      };
    }
    return {
      context: null,
      error: unauthorizedResponse("Unauthorized.", req),
    };
  }
}

/**
 * Checks if a user has a role in user_roles table.
 *
 * Expected table shape:
 * user_roles:
 * - user_id uuid
 * - role text
 */
export async function userHasRole(userId: string, role: UserRole): Promise<boolean> {
  const supabase = createServiceRoleClient();

  const { data, error } = await supabase
    .from("user_roles")
    .select("role")
    .eq("user_id", userId)
    .eq("role", role)
    .maybeSingle();

  if (error) {
    console.error("[auth] Failed to check user role:", error.message);
    return false;
  }

  return Boolean(data);
}

/**
 * Checks if a user is admin or super_admin.
 */
export async function isAdmin(userId: string): Promise<boolean> {
  const [admin, superAdmin] = await Promise.all([
    userHasRole(userId, "admin"),
    userHasRole(userId, "super_admin"),
  ]);

  return admin || superAdmin;
}

/** Resolve consumer plan_id from profiles (server-side only). */
export async function resolveUserPlanId(userId: string): Promise<string> {
  const supabase = createServiceRoleClient();
  const { data, error } = await supabase
    .from("profiles")
    .select("plan_id")
    .eq("id", userId)
    .maybeSingle();

  if (error) {
    console.error("[auth] resolveUserPlanId failed:", error.message);
    return "free";
  }

  return String(data?.plan_id ?? "free");
}

/**
 * Requires admin role.
 *
 * Throws if user is not admin.
 */
export async function requireAdmin(userId: string): Promise<void> {
  const allowed = await isAdmin(userId);

  if (!allowed) {
    throw new Error("Admin role required.");
  }
}

/**
 * Safe admin wrapper.
 *
 * Returns a 403 response if user is not admin.
 */
export async function enforceAdmin(userId: string): Promise<Response | null> {
  try {
    await requireAdmin(userId);
    return null;
  } catch {
    return forbiddenResponse("Admin access required.");
  }
}

/**
 * Requires the authenticated user to own the requested resource.
 *
 * If user is admin, ownership check is bypassed.
 */
export async function requireOwnershipOrAdmin(
  authenticatedUserId: string,
  resourceOwnerId: string
): Promise<void> {
  if (!authenticatedUserId || !resourceOwnerId) {
    throw new Error("Missing ownership identifiers.");
  }

  if (authenticatedUserId === resourceOwnerId) {
    return;
  }

  const allowed = await isAdmin(authenticatedUserId);

  if (!allowed) {
    throw new Error("Resource ownership required.");
  }
}

/**
 * Safe ownership/admin wrapper.
 */
export async function enforceOwnershipOrAdmin(
  authenticatedUserId: string,
  resourceOwnerId: string
): Promise<Response | null> {
  try {
    await requireOwnershipOrAdmin(authenticatedUserId, resourceOwnerId);
    return null;
  } catch {
    return forbiddenResponse("You do not have permission to access this resource.");
  }
}

/**
 * Checks ownership against a database table.
 *
 * Example:
 * await requireResourceOwnership({
 *   table: "sessions",
 *   resourceId: sessionId,
 *   resourceIdColumn: "id",
 *   ownerColumn: "user_id",
 *   authenticatedUserId: user.id,
 * });
 */
export async function requireResourceOwnership(options: {
  table: string;
  resourceId: string;
  resourceIdColumn?: string;
  ownerColumn?: string;
  authenticatedUserId: string;
}): Promise<void> {
  const {
    table,
    resourceId,
    resourceIdColumn = "id",
    ownerColumn = "user_id",
    authenticatedUserId,
  } = options;

  const supabase = createServiceRoleClient();

  const { data, error } = await supabase
    .from(table)
    .select(ownerColumn)
    .eq(resourceIdColumn, resourceId)
    .maybeSingle();

  if (error) {
    console.error("[auth] Failed to verify resource ownership:", error.message);
    throw new Error("Failed to verify resource ownership.");
  }

  if (!data) {
    throw new Error("Resource not found.");
  }

  const ownerId = data[ownerColumn] as string | undefined;

  if (!ownerId) {
    throw new Error("Resource owner not found.");
  }

  await requireOwnershipOrAdmin(authenticatedUserId, ownerId);
}

/**
 * Safe resource ownership wrapper.
 */
export async function enforceResourceOwnership(options: {
  table: string;
  resourceId: string;
  resourceIdColumn?: string;
  ownerColumn?: string;
  authenticatedUserId: string;
}): Promise<Response | null> {
  try {
    await requireResourceOwnership(options);
    return null;
  } catch {
    return forbiddenResponse("You do not have permission to access this resource.");
  }
}

/**
 * Extracts client IP from common reverse proxy headers.
 */
export function getClientIp(req: Request): string | null {
  const cfIp = req.headers.get("cf-connecting-ip");
  if (cfIp) return cfIp;

  const forwardedFor = req.headers.get("x-forwarded-for");
  if (forwardedFor) {
    return forwardedFor.split(",")[0]?.trim() ?? null;
  }

  const realIp = req.headers.get("x-real-ip");
  if (realIp) return realIp;

  return null;
}

/**
 * Extracts user agent.
 */
export function getUserAgent(req: Request): string | null {
  return req.headers.get("user-agent");
}

/**
 * Convenience helper for common Edge Function auth pattern.
 *
 * Usage:
 * const auth = await authenticateRequest(req);
 * if (auth.error) return auth.error;
 * const { user } = auth.context;
 */
export async function authenticateRequest(
  req: Request
): Promise<{ context: AuthContext; error: null } | { context: null; error: Response }> {
  return getAuthContext(req);
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

/**
 * Returns true when the given user is currently banned.
 * Fails closed (returns true) on DB errors for write/credit paths so a
 * transient outage cannot bypass suspension checks.
 */
export async function isUserBanned(
  db: SupabaseClient,
  userId: string,
): Promise<boolean> {
  const { data, error } = await db
    .from("profiles")
    .select("is_banned")
    .eq("id", userId)
    .maybeSingle();

  if (error) {
    console.error("[banCheck] lookup failed — treating as banned:", error.message);
    return true;
  }
  return !!(data as { is_banned?: boolean } | null)?.is_banned;
}

export function bannedResponse(corsHeaders: Record<string, string>) {
  return new Response(
    JSON.stringify({
      error: "Account suspended. Contact support.",
      code: "ACCOUNT_BANNED",
    }),
    {
      status: 403,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    },
  );
}
